/* ============================================================
   audio.js — âm thanh tổng hợp bằng Web Audio (không cần tệp ngoài)
   ============================================================ */
(function () {
  'use strict';

  class AudioEngine {
    constructor() {
      this.ctx = null;
      this.master = null;
      this.noiseBuf = null;
      this.enabled = true;
      this.ambientStarted = false;
    }

    init() {
      if (this.ctx) {
        if (this.ctx.state === 'suspended') this.ctx.resume();
        return;
      }
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) { this.enabled = false; return; }
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.36;
      this.master.connect(this.ctx.destination);

      const len = Math.floor(this.ctx.sampleRate * 1.2);
      this.noiseBuf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
      const data = this.noiseBuf.getChannelData(0);
      for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;

      this.startAmbient();
      if (this.ctx.state === 'suspended') this.ctx.resume();
    }

    startAmbient() {
      if (this.ambientStarted || !this.ctx) return;
      this.ambientStarted = true;
      const ctx = this.ctx;
      const src = ctx.createBufferSource();
      src.buffer = this.noiseBuf;
      src.loop = true;
      const filter = ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = 260;
      filter.Q.value = 0.8;
      const gain = ctx.createGain();
      gain.gain.value = 0.045;
      src.connect(filter).connect(gain).connect(this.master);

      const lfo = ctx.createOscillator();
      lfo.frequency.value = 0.07;
      const lfoGain = ctx.createGain();
      lfoGain.gain.value = 0.02;
      lfo.connect(lfoGain).connect(gain.gain);
      lfo.start();
      src.start();

      // distant industrial hum
      const hum = ctx.createOscillator();
      hum.type = 'sine';
      hum.frequency.value = 46;
      const hg = ctx.createGain();
      hg.gain.value = 0.012;
      hum.connect(hg).connect(this.master);
      hum.start();
    }

    now() { return this.ctx ? this.ctx.currentTime : 0; }

    tone({ freq = 440, end = null, dur = 0.15, type = 'sine', gain = 0.1, attack = 0.004, delay = 0 }) {
      if (!this.ctx || !this.enabled) return;
      const t = this.now() + delay;
      const o = this.ctx.createOscillator();
      const g = this.ctx.createGain();
      o.type = type;
      o.frequency.setValueAtTime(freq, t);
      if (end !== null) o.frequency.exponentialRampToValueAtTime(Math.max(20, end), t + dur);
      g.gain.setValueAtTime(0.0001, t);
      g.gain.linearRampToValueAtTime(gain, t + attack);
      g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      o.connect(g).connect(this.master);
      o.start(t);
      o.stop(t + dur + 0.02);
    }

    noise({ dur = 0.1, gain = 0.1, type = 'lowpass', freq = 1200, end = null, q = 0.7, delay = 0 }) {
      if (!this.ctx || !this.enabled) return;
      const t = this.now() + delay;
      const src = this.ctx.createBufferSource();
      src.buffer = this.noiseBuf;
      const f = this.ctx.createBiquadFilter();
      f.type = type;
      f.frequency.setValueAtTime(freq, t);
      if (end !== null) f.frequency.exponentialRampToValueAtTime(Math.max(40, end), t + dur);
      f.Q.value = q;
      const g = this.ctx.createGain();
      g.gain.setValueAtTime(0.0001, t);
      g.gain.linearRampToValueAtTime(gain, t + 0.006);
      g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      src.connect(f).connect(g).connect(this.master);
      src.start(t, Math.random() * 0.2);
      src.stop(t + dur + 0.02);
    }

    shoot(id) {
      if (!this.ctx) return;
      if (id === 'pistol') {
        this.noise({ dur: 0.09, gain: 0.2, type: 'highpass', freq: 900, end: 500 });
        this.tone({ freq: 165, end: 55, dur: 0.1, type: 'triangle', gain: 0.16 });
      } else if (id === 'shotgun') {
        this.noise({ dur: 0.26, gain: 0.3, type: 'lowpass', freq: 2200, end: 300 });
        this.tone({ freq: 105, end: 34, dur: 0.22, type: 'triangle', gain: 0.24 });
      } else if (id === 'rifle') {
        this.noise({ dur: 0.07, gain: 0.17, type: 'highpass', freq: 1300, end: 700 });
        this.tone({ freq: 220, end: 70, dur: 0.07, type: 'square', gain: 0.1 });
      } else if (id === 'turret') {
        this.noise({ dur: 0.05, gain: 0.08, type: 'bandpass', freq: 1900, q: 1.4 });
        this.tone({ freq: 300, end: 120, dur: 0.05, type: 'square', gain: 0.04 });
      } else if (id === 'soldier') {
        this.noise({ dur: 0.075, gain: 0.1, type: 'highpass', freq: 1000 });
        this.tone({ freq: 190, end: 70, dur: 0.07, type: 'triangle', gain: 0.07 });
      } else {
        this.noise({ dur: 0.1, gain: 0.12, type: 'bandpass', freq: 1500, q: 1.2 });
      }
    }

    melee() {
      this.noise({ dur: 0.14, gain: 0.14, type: 'bandpass', freq: 1800, end: 500, q: 1.8 });
      this.tone({ freq: 320, end: 140, dur: 0.08, type: 'sawtooth', gain: 0.03 });
    }

    hit() {
      this.noise({ dur: 0.08, gain: 0.13, type: 'lowpass', freq: 700, end: 180 });
      this.tone({ freq: 120, end: 60, dur: 0.09, type: 'triangle', gain: 0.09 });
    }

    kill() {
      this.noise({ dur: 0.2, gain: 0.14, type: 'lowpass', freq: 500, end: 120 });
      this.tone({ freq: 90, end: 35, dur: 0.22, type: 'sawtooth', gain: 0.07 });
    }

    hurt() {
      this.tone({ freq: 190, end: 55, dur: 0.25, type: 'sawtooth', gain: 0.12 });
      this.noise({ dur: 0.25, gain: 0.12, type: 'lowpass', freq: 400, end: 100 });
    }

    pickup(good = false) {
      this.tone({ freq: good ? 620 : 480, end: good ? 980 : 700, dur: 0.12, type: 'sine', gain: 0.07 });
      this.tone({ freq: good ? 940 : 720, end: good ? 1320 : 980, dur: 0.14, type: 'sine', gain: 0.045, delay: 0.06 });
    }

    build() {
      this.tone({ freq: 140, end: 70, dur: 0.1, type: 'square', gain: 0.07 });
      this.tone({ freq: 110, end: 55, dur: 0.14, type: 'triangle', gain: 0.1, delay: 0.1 });
      this.noise({ dur: 0.12, gain: 0.08, type: 'lowpass', freq: 900, delay: 0.1 });
    }

    levelup() {
      [523.25, 659.25, 783.99, 1046.5].forEach((f, i) => {
        this.tone({ freq: f, dur: 0.35, type: 'triangle', gain: 0.07, delay: i * 0.09 });
        this.tone({ freq: f * 2, dur: 0.2, type: 'sine', gain: 0.025, delay: i * 0.09 });
      });
    }

    quest() {
      this.tone({ freq: 587, end: 784, dur: 0.18, type: 'triangle', gain: 0.07 });
      this.tone({ freq: 880, end: 1174, dur: 0.28, type: 'sine', gain: 0.05, delay: 0.12 });
    }

    wave() {
      this.tone({ freq: 70, end: 42, dur: 1.1, type: 'sawtooth', gain: 0.1 });
      this.tone({ freq: 105, end: 63, dur: 1.2, type: 'triangle', gain: 0.05, delay: 0.05 });
      this.noise({ dur: 1.4, gain: 0.06, type: 'lowpass', freq: 300, end: 90 });
    }

    explosion() {
      this.noise({ dur: 0.7, gain: 0.35, type: 'lowpass', freq: 1400, end: 60 });
      this.tone({ freq: 80, end: 22, dur: 0.55, type: 'sawtooth', gain: 0.22 });
    }

    empty() {
      this.tone({ freq: 190, dur: 0.035, type: 'square', gain: 0.05 });
    }

    reload() {
      this.tone({ freq: 300, dur: 0.04, type: 'square', gain: 0.04 });
      this.tone({ freq: 210, dur: 0.05, type: 'square', gain: 0.05, delay: 0.18 });
    }

    heal() {
      this.tone({ freq: 330, end: 440, dur: 0.3, type: 'sine', gain: 0.06 });
      this.tone({ freq: 495, end: 660, dur: 0.35, type: 'sine', gain: 0.04, delay: 0.08 });
    }

    click() {
      this.tone({ freq: 720, dur: 0.03, type: 'square', gain: 0.025 });
    }

    error() {
      this.tone({ freq: 150, end: 110, dur: 0.16, type: 'square', gain: 0.06 });
    }

    bossRoar() {
      this.tone({ freq: 55, end: 28, dur: 1.6, type: 'sawtooth', gain: 0.18 });
      this.noise({ dur: 1.5, gain: 0.12, type: 'lowpass', freq: 500, end: 80 });
    }
  }

  TT.AudioEngine = AudioEngine;
  TT.audio = new AudioEngine();
})();

/* ============================================================
   world.js — sinh bản đồ, địa hình, đổ nát, căn cứ
   ============================================================ */
(function () {
  'use strict';
  const U = TT.U;

  class World {
    constructor(game) {
      this.game = game;
      this.size = 4200;
      this.base = {
        x: 2100, y: 2100, r: 310,
        command: { x: 2100, y: 1968 },
        fire: { x: 2242, y: 2172 },
        antenna: { x: 1908, y: 1930 },
        tents: [{ x: 1938, y: 2178, w: 96, h: 76 }, { x: 2282, y: 2024, w: 80, h: 68 }],
        spawn: { x: 2100, y: 2190 },
      };
      this.reset();
    }

    reset() {
      this.obstacles = [];
      this.buildings = [];
      this.loots = [];
      this.explosives = [];
      this.decals = [];
      this.baseProps = [];
      this.explored = new Set();
      this.generate();
      this.seedExplored();
    }

    seedExplored() {
      for (let dx = -6; dx <= 6; dx++) {
        for (let dy = -6; dy <= 6; dy++) {
          if (dx * dx + dy * dy < 40) this.explored.add(`${dx + 21},${dy + 21}`);
        }
      }
    }

    markExplored(x, y, radius = 480) {
      const cell = 100;
      const cx = Math.floor(x / cell), cy = Math.floor(y / cell);
      const rr = Math.ceil(radius / cell);
      for (let dx = -rr; dx <= rr; dx++) {
        for (let dy = -rr; dy <= rr; dy++) {
          if (dx * dx + dy * dy > rr * rr) continue;
          this.explored.add(`${cx + dx},${cy + dy}`);
        }
      }
    }

    isExplored(x, y) {
      return this.explored.has(`${Math.floor(x / 100)},${Math.floor(y / 100)}`);
    }

    generate() {
      const rng = U.mulberry32(20771);
      const R = (a, b) => a + rng() * (b - a);
      const SIZE = this.size;

      // Vành đai đổ nát quanh biên bản đồ
      const border = 70;
      this.obstacles.push(
        { x: -60, y: -60, w: SIZE + 120, h: border, kind: 'rubble-edge', seed: 1, solid: true },
        { x: -60, y: SIZE - 10, w: SIZE + 120, h: border, kind: 'rubble-edge', seed: 2, solid: true },
        { x: -60, y: 0, w: border, h: SIZE, kind: 'rubble-edge', seed: 3, solid: true },
        { x: SIZE - 10, y: 0, w: border, h: SIZE, kind: 'rubble-edge', seed: 4, solid: true },
      );

      // ---- Nhà đổ nát ----
      let attempts = 0;
      while (this.buildings.length < 26 && attempts < 500) {
        attempts++;
        const w = Math.round(R(150, 360) / 20) * 20;
        const h = Math.round(R(130, 280) / 20) * 20;
        const x = Math.round(R(180, SIZE - 180 - w));
        const y = Math.round(R(180, SIZE - 180 - h));
        if (U.dist(x + w / 2, y + h / 2, this.base.x, this.base.y) < 520) continue;
        if (this.tooCloseToBuilding(x, y, w, h)) continue;
        if (this.onRoad(x, y, w, h, 30)) continue;
        this.buildBuilding(x, y, w, h, rng);
      }

      // ---- Ô tô hỏng dọc đường ----
      const roadSpots = [];
      for (let i = 0; i < 8; i++) {
        roadSpots.push({ x: R(350, SIZE - 350), y: 2100 + R(-50, 50), vertical: true });
        roadSpots.push({ x: 2100 + R(-55, 55), y: R(350, SIZE - 350), vertical: false });
      }
      for (let i = 0; i < 6; i++) {
        roadSpots.push({ x: R(300, SIZE - 300), y: 850 + R(-30, 30), vertical: true });
        roadSpots.push({ x: 850 + R(-30, 30), y: R(300, SIZE - 300), vertical: false });
        roadSpots.push({ x: R(300, SIZE - 300), y: 3350 + R(-30, 30), vertical: true });
        roadSpots.push({ x: 3350 + R(-30, 30), y: R(300, SIZE - 300), vertical: false });
      }
      for (const spot of roadSpots) {
        if (U.dist(spot.x, spot.y, this.base.x, this.base.y) < 420) continue;
        if (rng() > 0.62) continue;
        const vertical = spot.vertical;
        const w = vertical ? 62 : 112;
        const h = vertical ? 112 : 62;
        if (this.overlapsAny(spot.x - w / 2, spot.y - h / 2, w, h, 30)) continue;
        this.obstacles.push({ x: spot.x - w / 2, y: spot.y - h / 2, w, h, kind: 'car', seed: rng() * 999, solid: true });
      }

      // ---- Cây chết ----
      for (let i = 0; i < 100; i++) {
        const x = R(180, SIZE - 180), y = R(180, SIZE - 180);
        if (U.dist(x, y, this.base.x, this.base.y) < 400) continue;
        if (this.overlapsAny(x - 20, y - 20, 40, 40, 45)) continue;
        if (this.onRoad(x - 20, y - 20, 40, 40, 10)) continue;
        this.obstacles.push({ x: x - 17, y: y - 17, w: 34, h: 34, kind: 'tree', seed: rng() * 999, solid: true });
      }

      // ---- Đá tảng ----
      for (let i = 0; i < 55; i++) {
        const x = R(180, SIZE - 180), y = R(180, SIZE - 180);
        const s = R(28, 62);
        if (U.dist(x, y, this.base.x, this.base.y) < 360) continue;
        if (this.overlapsAny(x - s / 2, y - s / 2, s, s, 25)) continue;
        this.obstacles.push({ x: x - s / 2, y: y - s / 2, w: s, h: s * 0.86, kind: 'rock', seed: rng() * 999, solid: true });
      }

      // ---- Thùng nổ ----
      for (let i = 0; i < 34; i++) {
        const x = R(250, SIZE - 250), y = R(250, SIZE - 250);
        if (U.dist(x, y, this.base.x, this.base.y) < 380) continue;
        if (this.overlapsAny(x - 14, y - 14, 28, 28, 20)) continue;
        const ob = { x: x - 13, y: y - 13, w: 26, h: 26, kind: 'barrel', seed: rng() * 999, solid: true, hp: 24, explosive: true };
        this.obstacles.push(ob);
        this.explosives.push(ob);
      }

      // ---- Vật tư rải rác ----
      for (let i = 0; i < 72; i++) {
        const x = R(220, SIZE - 220), y = R(220, SIZE - 220);
        if (U.dist(x, y, this.base.x, this.base.y) < 390) continue;
        if (this.pointBlocked(x, y, 22)) continue;
        if (this.loots.some(l => U.dist(l.x, l.y, x, y) < 90)) continue;
        let type = 'crate';
        const roll = rng();
        if (roll > 0.76) type = 'duffel';
        else if (roll > 0.64) type = 'corpse';
        else if (roll > 0.56) type = 'locker';
        this.loots.push(this.makeLoot(x, y, type, rng));
      }

      // ---- Kho vũ khí đặc biệt ----
      const cachePositions = [
        { x: 860, y: 1460 }, { x: 3420, y: 1120 }, { x: 3080, y: 3420 },
        { x: 1280, y: 3250 }, { x: 3680, y: 2640 }, { x: 520, y: 2780 },
      ];
      for (const p of cachePositions) {
        if (this.pointBlocked(p.x, p.y, 30)) {
          p.x += 55; p.y += 35;
        }
        const loot = this.makeLoot(p.x, p.y, 'weapon', rng);
        loot.weaponCache = true;
        this.loots.push(loot);
      }

      // ---- Xác và vết máu cũ ----
      for (let i = 0; i < 75; i++) {
        const b = this.buildings[Math.floor(rng() * this.buildings.length)];
        if (!b) break;
        const x = b.x + R(30, b.w - 30), y = b.y + R(30, b.h - 30);
        this.decals.push({ type: 'blood', x, y, r: R(12, 34), rot: R(0, 6.28), seed: rng() * 100 });
      }
      for (let i = 0; i < 650; i++) {
        const x = R(100, SIZE - 100), y = R(100, SIZE - 100);
        const roll = rng();
        let type = 'patch';
        if (roll > 0.72) type = 'tuft';
        else if (roll > 0.55) type = 'debris';
        else if (roll > 0.49) type = 'crack';
        this.decals.push({ type, x, y, r: R(8, 42), rot: R(0, 6.28), seed: rng() * 100 });
      }

      // ---- Vật cản quanh căn cứ ----
      const base = this.base;
      const sandbags = [
        { x: base.x - 280, y: base.y - 90, w: 76, h: 26, a: -0.3 },
        { x: base.x - 240, y: base.y + 170, w: 76, h: 26, a: 0.55 },
        { x: base.x + 260, y: base.y - 130, w: 76, h: 26, a: -0.7 },
        { x: base.x + 220, y: base.y + 200, w: 76, h: 26, a: 0.2 },
      ];
      for (const sb of sandbags) {
        this.obstacles.push({ x: sb.x, y: sb.y, w: sb.w, h: sb.h, kind: 'sandbag', seed: rng() * 999, solid: true, angle: sb.a });
      }

      // ---- Vật trang trí căn cứ ----
      this.baseProps = [
        { type: 'antenna', x: base.antenna.x, y: base.antenna.y },
        { type: 'generator', x: base.x + 195, y: base.y - 95 },
        { type: 'barrel', x: base.x + 245, y: base.y - 40 },
        { type: 'barrel', x: base.x + 262, y: base.y - 4 },
        { type: 'crate', x: base.x - 180, y: base.y + 90 },
        { type: 'crate', x: base.x - 196, y: base.y + 70 },
        { type: 'flag', x: base.x - 60, y: base.y - 168 },
      ];

      // Thùng tiếp tế ban đầu trong căn cứ
      const supply = this.makeLoot(base.x + 160, base.y + 118, 'supply', rng);
      supply.baseSupply = true;
      this.loots.push(supply);
    }

    makeLoot(x, y, type, rng) {
      const r = rng || Math.random;
      return {
        x, y, type, opened: false,
        seed: r() * 999, phase: r() * 6.28,
        far: U.dist(x, y, this.base.x, this.base.y) / this.size,
        weaponCache: false, baseSupply: false,
        label: type === 'weapon' ? 'KHO VŨ KHÍ' : null,
      };
    }

    tooCloseToBuilding(x, y, w, h) {
      return this.buildings.some(b => {
        return x < b.x + b.w + 110 && x + w + 110 > b.x && y < b.y + b.h + 110 && y + h + 110 > b.y;
      });
    }

    onRoad(x, y, w, h, pad) {
      const roads = this.roadRects();
      return roads.some(r => x < r.x + r.w + pad && x + w + pad > r.x && y < r.y + r.h + pad && y + h + pad > r.y);
    }

    roadRects() {
      return [
        { x: 0, y: 2020, w: this.size, h: 160 },
        { x: 2020, y: 0, w: 160, h: this.size },
        { x: 0, y: 800, w: this.size, h: 100 },
        { x: 800, y: 0, w: 100, h: this.size },
        { x: 0, y: 3300, w: this.size, h: 100 },
        { x: 3300, y: 0, w: 100, h: this.size },
      ];
    }

    overlapsAny(x, y, w, h, pad) {
      const rect = { x: x - pad, y: y - pad, w: w + pad * 2, h: h + pad * 2 };
      return this.obstacles.some(o => o.kind !== 'rubble-edge' && x < o.x + o.w + pad && x + w + pad > o.x && y < o.y + o.h + pad && y + h + pad > o.y);
    }

    pointBlocked(x, y, r) {
      return this.obstacles.some(o => o.solid && U.circleRect(x, y, r, o));
    }

    buildBuilding(x, y, w, h, rng) {
      const building = { x, y, w, h, seed: rng() * 999, floors: [], walls: [] };
      const t = 18;
      const gapSide = Math.floor(rng() * 4);
      const gapStart = 0.32 + rng() * 0.2;
      const gapLen = 0.16 + rng() * 0.12;

      const makeWall = (wx, wy, ww, wh, side) => {
        const horizontal = ww > wh;
        const start = horizontal ? (wx - x) / w : (wy - y) / h;
        const len = horizontal ? ww / w : wh / h;
        const inGap = side === gapSide && start < gapStart + gapLen && start + len > gapStart;
        if (inGap) return;
        if (side !== gapSide && rng() < 0.11) return;
        const ob = { x: wx, y: wy, w: ww, h: wh, kind: 'wall', seed: rng() * 999, solid: true };
        this.obstacles.push(ob);
        building.walls.push(ob);
      };

      makeWall(x, y, w, t, 0);
      makeWall(x, y + h - t, w, t, 2);
      makeWall(x, y + t, t, h - t * 2, 1);
      makeWall(x + w - t, y + t, t, h - t * 2, 3);
      this.buildings.push(building);

      // nội thất đổ nát
      const innerCount = 1 + Math.floor(rng() * 3);
      for (let i = 0; i < innerCount; i++) {
        const iw = 30 + rng() * 60, ih = 20 + rng() * 40;
        const ix = x + 30 + rng() * (w - 60 - iw);
        const iy = y + 30 + rng() * (h - 60 - ih);
        if (ix + iw > x + w - 24 || iy + ih > y + h - 24) continue;
        this.obstacles.push({ x: ix, y: iy, w: iw, h: ih, kind: rng() > 0.55 ? 'shelf' : 'rubble', seed: rng() * 999, solid: true });
      }

      // vật tư trong nhà
      const lootCount = 2 + Math.floor(rng() * 3);
      for (let i = 0; i < lootCount; i++) {
        const lx = x + 50 + rng() * (w - 100);
        const ly = y + 50 + rng() * (h - 100);
        if (this.pointBlocked(lx, ly, 16)) continue;
        const r = rng();
        this.loots.push(this.makeLoot(lx, ly, r > 0.68 ? 'locker' : r > 0.38 ? 'crate' : 'duffel', rng));
      }

      // mảng nứt sàn
      this.decals.push({ type: 'floor', x, y, w, h, seed: rng() * 99 });
    }

    // ============================================================
    //  VẼ ĐỊA HÌNH
    // ============================================================
    drawGround(ctx, view) {
      const SIZE = this.size;
      const tile = 80;
      const x0 = Math.max(0, Math.floor(view.left / tile));
      const x1 = Math.min(Math.ceil(SIZE / tile), Math.ceil(view.right / tile));
      const y0 = Math.max(0, Math.floor(view.top / tile));
      const y1 = Math.min(Math.ceil(SIZE / tile), Math.ceil(view.bottom / tile));

      for (let ty = y0; ty < y1; ty++) {
        for (let tx = x0; tx < x1; tx++) {
          const h = U.hash(tx, ty, 3);
          const r = 27 + h * 8;
          const g = 32 + h * 9;
          const b = 23 + h * 7;
          ctx.fillStyle = `rgb(${r | 0},${g | 0},${b | 0})`;
          ctx.fillRect(tx * tile - 1, ty * tile - 1, tile + 2, tile + 2);
        }
      }

      // đường nhựa
      ctx.save();
      for (const road of this.roadRects()) {
        if (road.x + road.w < view.left || road.x > view.right || road.y + road.h < view.top || road.y > view.bottom) continue;
        const main = road.w > 140 || road.h > 140;
        ctx.fillStyle = main ? '#242622' : '#222420';
        ctx.fillRect(road.x, road.y, road.w, road.h);
        // mép đường
        ctx.fillStyle = 'rgba(78,76,61,0.55)';
        if (road.w > road.h) {
          ctx.fillRect(road.x, road.y, road.w, 4);
          ctx.fillRect(road.x, road.y + road.h - 4, road.w, 4);
        } else {
          ctx.fillRect(road.x, road.y, 4, road.h);
          ctx.fillRect(road.x + road.w - 4, road.y, 4, road.h);
        }
        // vạch kẻ mờ
        ctx.strokeStyle = main ? 'rgba(196,164,84,0.22)' : 'rgba(180,168,120,0.14)';
        ctx.lineWidth = main ? 5 : 3;
        ctx.setLineDash([main ? 46 : 30, main ? 36 : 42]);
        ctx.beginPath();
        if (road.w > road.h) {
          const cy = road.y + road.h / 2;
          ctx.moveTo(Math.max(view.left, road.x), cy);
          ctx.lineTo(Math.min(view.right, road.x + road.w), cy);
        } else {
          const cx = road.x + road.w / 2;
          ctx.moveTo(cx, Math.max(view.top, road.y));
          ctx.lineTo(cx, Math.min(view.bottom, road.y + road.h));
        }
        ctx.stroke();
        ctx.setLineDash([]);
      }
      ctx.restore();

      // vết nứt, bụi, cỏ khô
      for (const d of this.decals) {
        if (d.x < view.left - 80 || d.x > view.right + 80 || d.y < view.top - 80 || d.y > view.bottom + 80) continue;
        if (d.type === 'patch') {
          ctx.fillStyle = U.hash(d.x | 0, d.y | 0, 9) > 0.5 ? 'rgba(45,50,33,0.34)' : 'rgba(18,22,16,0.32)';
          ctx.beginPath();
          ctx.ellipse(d.x, d.y, d.r * 1.6, d.r * 0.8, d.rot, 0, U.TAU);
          ctx.fill();
        } else if (d.type === 'tuft') {
          ctx.strokeStyle = 'rgba(92,96,54,0.34)';
          ctx.lineWidth = 1.2;
          for (let i = 0; i < 4; i++) {
            const a = d.rot + i * 0.4;
            ctx.beginPath();
            ctx.moveTo(d.x, d.y);
            ctx.lineTo(d.x + Math.cos(a) * (5 + i * 2), d.y + Math.sin(a) * (5 + i * 2) - 5);
            ctx.stroke();
          }
        } else if (d.type === 'debris') {
          ctx.fillStyle = 'rgba(89,84,66,0.5)';
          ctx.fillRect(d.x, d.y, 5, 3);
          ctx.fillRect(d.x + 7, d.y - 4, 3, 2);
        } else if (d.type === 'crack') {
          ctx.strokeStyle = 'rgba(9,11,8,0.36)';
          ctx.lineWidth = 1;
          ctx.beginPath();
          ctx.moveTo(d.x, d.y);
          let px = d.x, py = d.y;
          for (let i = 0; i < 4; i++) {
            const a = d.rot + Math.sin(d.seed + i) * 1.1;
            px += Math.cos(a) * 9; py += Math.sin(a) * 9;
            ctx.lineTo(px, py);
          }
          ctx.stroke();
        } else if (d.type === 'blood') {
          ctx.fillStyle = 'rgba(64,24,18,0.34)';
          ctx.beginPath();
          ctx.ellipse(d.x, d.y, d.r, d.r * 0.55, d.rot, 0, U.TAU);
          ctx.fill();
        } else if (d.type === 'floor') {
          ctx.fillStyle = 'rgba(72,70,57,0.2)';
          ctx.fillRect(d.x, d.y, d.w, d.h);
        }
      }

      this.drawBaseGround(ctx, view);
    }

    drawBaseGround(ctx, view) {
      const b = this.base;
      if (b.x + b.r < view.left || b.x - b.r > view.right || b.y + b.r < view.top || b.y - b.r > view.bottom) return;
      ctx.save();
      ctx.fillStyle = '#37382e';
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, U.TAU);
      ctx.fill();
      ctx.strokeStyle = 'rgba(130,126,96,0.4)';
      ctx.lineWidth = 6;
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r - 8, 0, U.TAU);
      ctx.stroke();
      ctx.strokeStyle = 'rgba(18,20,16,0.6)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r - 26, 0, U.TAU);
      ctx.stroke();

      // vạch cảnh báo
      ctx.strokeStyle = 'rgba(211,151,57,0.35)';
      ctx.lineWidth = 4;
      ctx.setLineDash([16, 14]);
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r - 44, 0, U.TAU);
      ctx.stroke();
      ctx.setLineDash([]);

      // vết nứt sàn
      for (let i = 0; i < 12; i++) {
        const a = (i / 12) * U.TAU + 0.24;
        const rr = 100 + (i * 47) % 160;
        ctx.strokeStyle = 'rgba(20,22,17,0.35)';
        ctx.lineWidth = 1.4;
        ctx.beginPath();
        const sx = b.x + Math.cos(a) * rr, sy = b.y + Math.sin(a) * rr * 0.9;
        ctx.moveTo(sx, sy);
        ctx.lineTo(sx + Math.cos(a + 0.8) * 20, sy + Math.sin(a + 0.8) * 12);
        ctx.lineTo(sx + Math.cos(a + 0.2) * 34, sy + Math.sin(a + 0.2) * 22);
        ctx.stroke();
      }

      // chữ 07 trên sàn
      ctx.save();
      ctx.translate(b.x, b.y + 175);
      ctx.rotate(-0.04);
      ctx.font = '900 64px "Segoe UI", Arial, sans-serif';
      ctx.fillStyle = 'rgba(216,209,177,0.09)';
      ctx.textAlign = 'center';
      ctx.fillText('07', 0, 0);
      ctx.restore();

      // lối vào
      ctx.fillStyle = 'rgba(187,164,103,0.2)';
      ctx.fillRect(b.x - 46, b.y + b.r - 14, 92, 24);

      ctx.restore();
    }

    drawProps(ctx, view) {
      for (const o of this.obstacles) {
        if (o.x + o.w < view.left - 100 || o.x > view.right + 100 || o.y + o.h < view.top - 100 || o.y > view.bottom + 100) continue;
        this.drawObstacle(ctx, o);
      }
      // trang trí căn cứ
      for (const p of this.baseProps) {
        if (p.x < view.left - 120 || p.x > view.right + 120 || p.y < view.top - 120 || p.y > view.bottom + 120) continue;
        this.drawBaseProp(ctx, p);
      }
      this.drawBaseStructures(ctx, view);
    }

    drawObstacle(ctx, o) {
      const s = o.seed || 0;
      switch (o.kind) {
        case 'wall': {
          ctx.fillStyle = 'rgba(5,7,5,0.4)';
          ctx.fillRect(o.x + 5, o.y + 7, o.w, o.h);
          ctx.fillStyle = '#3f4237';
          ctx.fillRect(o.x, o.y, o.w, o.h);
          ctx.fillStyle = '#4c4e41';
          ctx.fillRect(o.x, o.y, o.w, Math.max(4, o.h * 0.34));
          // gạch nứt
          ctx.strokeStyle = 'rgba(17,19,14,0.45)';
          ctx.lineWidth = 1;
          const n = Math.max(1, Math.floor((o.w + o.h) / 42));
          for (let i = 0; i < n; i++) {
            const hx = o.x + U.hash(i, s, 4) * o.w;
            const hy = o.y + U.hash(i, s, 6) * o.h;
            ctx.beginPath();
            ctx.moveTo(hx, hy);
            ctx.lineTo(hx + 6, hy + 4);
            ctx.lineTo(hx + 9, hy + 1);
            ctx.stroke();
          }
          if (s % 5 < 2) {
            ctx.fillStyle = 'rgba(83,102,55,0.28)';
            ctx.fillRect(o.x + (s * 13) % Math.max(1, o.w - 10), o.y + o.h - 6, 12, 6);
          }
          break;
        }
        case 'car': {
          this.drawCar(ctx, o);
          break;
        }
        case 'tree': {
          const cx = o.x + o.w / 2, cy = o.y + o.h / 2;
          ctx.fillStyle = 'rgba(4,6,4,0.35)';
          ctx.beginPath();
          ctx.ellipse(cx + 14, cy + 14, 46, 16, 0.5, 0, U.TAU);
          ctx.fill();
          ctx.strokeStyle = '#403b2d';
          ctx.lineCap = 'round';
          ctx.lineWidth = 6;
          ctx.beginPath();
          ctx.moveTo(cx, cy + 10);
          ctx.lineTo(cx + Math.sin(s) * 6, cy - 22);
          ctx.stroke();
          ctx.lineWidth = 3;
          for (let i = 0; i < 5; i++) {
            const a = s + i * 1.2;
            ctx.beginPath();
            ctx.moveTo(cx + Math.sin(s) * 3, cy - 10 - i * 2);
            ctx.lineTo(cx + Math.cos(a) * (20 + i * 3), cy - 16 - i * 3 + Math.sin(a) * 15);
            ctx.stroke();
          }
          ctx.fillStyle = '#3a3529';
          ctx.beginPath();
          ctx.arc(cx, cy, 7, 0, U.TAU);
          ctx.fill();
          break;
        }
        case 'rock': {
          const cx = o.x + o.w / 2, cy = o.y + o.h / 2;
          ctx.fillStyle = 'rgba(4,6,4,0.32)';
          ctx.beginPath();
          ctx.ellipse(cx + 6, cy + 9, o.w * 0.52, o.h * 0.36, 0.3, 0, U.TAU);
          ctx.fill();
          ctx.fillStyle = s % 3 === 0 ? '#494b41' : '#43453b';
          ctx.beginPath();
          for (let i = 0; i < 7; i++) {
            const a = (i / 7) * U.TAU;
            const rr = (0.4 + U.hash(i, s, 2) * 0.14);
            const px = cx + Math.cos(a) * o.w * rr;
            const py = cy + Math.sin(a) * o.h * rr;
            if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
          }
          ctx.closePath();
          ctx.fill();
          ctx.fillStyle = 'rgba(150,148,124,0.13)';
          ctx.beginPath();
          ctx.ellipse(cx - o.w * 0.1, cy - o.h * 0.12, o.w * 0.24, o.h * 0.14, -0.5, 0, U.TAU);
          ctx.fill();
          break;
        }
        case 'barrel': {
          const cx = o.x + o.w / 2, cy = o.y + o.h / 2;
          ctx.fillStyle = 'rgba(4,6,4,0.36)';
          ctx.beginPath();
          ctx.ellipse(cx + 5, cy + 6, 15, 10, 0.3, 0, U.TAU);
          ctx.fill();
          ctx.fillStyle = '#6c4b31';
          ctx.beginPath();
          ctx.arc(cx, cy, 12, 0, U.TAU);
          ctx.fill();
          ctx.strokeStyle = '#3d2b1d';
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.arc(cx, cy, 8, 0, U.TAU);
          ctx.stroke();
          ctx.fillStyle = '#b89a51';
          ctx.fillRect(cx - 12, cy - 4, 24, 3);
          ctx.fillStyle = 'rgba(24,14,8,0.5)';
          ctx.beginPath();
          ctx.arc(cx - 4, cy - 4, 3, 0, U.TAU);
          ctx.fill();
          break;
        }
        case 'sandbag': {
          const cx = o.x + o.w / 2, cy = o.y + o.h / 2;
          ctx.save();
          ctx.translate(cx, cy);
          ctx.rotate(o.angle || 0);
          ctx.fillStyle = 'rgba(4,6,4,0.3)';
          ctx.fillRect(-o.w / 2 + 4, -o.h / 2 + 6, o.w, o.h);
          for (let i = 0; i < 3; i++) {
            ctx.fillStyle = i % 2 ? '#7b704c' : '#857a54';
            ctx.beginPath();
            ctx.ellipse(-o.w / 2 + 14 + i * 25, 0, 17, 12, 0, 0, U.TAU);
            ctx.fill();
            ctx.strokeStyle = 'rgba(57,50,31,0.5)';
            ctx.lineWidth = 1;
            ctx.stroke();
          }
          ctx.restore();
          break;
        }
        case 'shelf': {
          ctx.fillStyle = 'rgba(4,6,4,0.3)';
          ctx.fillRect(o.x + 4, o.y + 5, o.w, o.h);
          ctx.fillStyle = '#3b382c';
          ctx.fillRect(o.x, o.y, o.w, o.h);
          ctx.strokeStyle = 'rgba(140,128,90,0.35)';
          ctx.lineWidth = 1;
          for (let i = 1; i < 3; i++) {
            ctx.beginPath();
            ctx.moveTo(o.x, o.y + (o.h / 3) * i);
            ctx.lineTo(o.x + o.w, o.y + (o.h / 3) * i);
            ctx.stroke();
          }
          break;
        }
        case 'rubble': {
          ctx.fillStyle = 'rgba(4,6,4,0.3)';
          ctx.fillRect(o.x + 4, o.y + 4, o.w, o.h);
          for (let i = 0; i < 7; i++) {
            const px = o.x + U.hash(i, s, 1) * o.w;
            const py = o.y + U.hash(i, s, 2) * o.h;
            ctx.fillStyle = i % 2 ? '#47463a' : '#3a3a2f';
            ctx.fillRect(px, py, 6 + (i % 3) * 4, 4 + (i % 2) * 4);
          }
          break;
        }
        case 'rubble-edge': {
          break;
        }
        default: {
          ctx.fillStyle = '#3b3d32';
          ctx.fillRect(o.x, o.y, o.w, o.h);
        }
      }
    }

    drawCar(ctx, o) {
      const cx = o.x + o.w / 2, cy = o.y + o.h / 2;
      const vertical = o.h > o.w;
      const w = vertical ? o.w : o.w;
      const h = vertical ? o.h : o.h;
      const s = o.seed || 0;
      const palette = [
        ['#6f3e2c', '#512b1e'], ['#3f4f51', '#2c3839'], ['#6a6440', '#4d482e'], ['#5b4a3c', '#40332a'],
      ];
      const col = palette[Math.floor(s) % palette.length];
      ctx.save();
      ctx.translate(cx, cy);
      if (!vertical) ctx.rotate(Math.PI / 2);
      ctx.fillStyle = 'rgba(3,5,3,0.4)';
      ctx.beginPath();
      ctx.roundRect(-w / 2 + 5, -h / 2 + 8, w, h, 10);
      ctx.fill();
      ctx.fillStyle = col[0];
      ctx.beginPath();
      ctx.roundRect(-w / 2, -h / 2, w, h, 11);
      ctx.fill();
      ctx.fillStyle = col[1];
      ctx.beginPath();
      ctx.roundRect(-w / 2 + 7, -h / 2 + 8, w - 14, h - 16, 7);
      ctx.fill();
      // kính
      ctx.fillStyle = 'rgba(23,33,34,0.82)';
      ctx.beginPath();
      ctx.roundRect(-w / 2 + 10, -h / 2 + 16, w - 20, 17, 3);
      ctx.fill();
      ctx.beginPath();
      ctx.roundRect(-w / 2 + 10, h / 2 - 34, w - 20, 16, 3);
      ctx.fill();
      // nóc
      ctx.fillStyle = 'rgba(190,183,150,0.1)';
      ctx.fillRect(-w / 2 + 12, -h / 2 + 38, w - 24, h - 76);
      // bánh xe
      ctx.fillStyle = '#151713';
      ctx.fillRect(-w / 2 - 3, -h / 2 + 14, 7, 16);
      ctx.fillRect(w / 2 - 4, -h / 2 + 14, 7, 16);
      ctx.fillRect(-w / 2 - 3, h / 2 - 30, 7, 16);
      ctx.fillRect(w / 2 - 4, h / 2 - 30, 7, 16);
      // gỉ sét
      ctx.fillStyle = 'rgba(99,63,37,0.45)';
      ctx.beginPath();
      ctx.ellipse(-w * 0.2, h * 0.22, 8, 12, 0.4, 0, U.TAU);
      ctx.fill();
      ctx.restore();
    }

    drawBaseProp(ctx, p) {
      if (p.type === 'antenna') {
        ctx.strokeStyle = 'rgba(4,6,4,0.35)';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.ellipse(p.x + 8, p.y + 12, 26, 10, 0.4, 0, U.TAU);
        ctx.stroke();
        ctx.strokeStyle = '#4f5546';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(p.x, p.y + 8); ctx.lineTo(p.x, p.y - 54); ctx.stroke();
        for (let i = 0; i < 3; i++) {
          const yy = p.y - 10 - i * 16;
          ctx.beginPath();
          ctx.moveTo(p.x - 12 + i * 2, yy); ctx.lineTo(p.x, yy - 9); ctx.lineTo(p.x + 12 - i * 2, yy);
          ctx.stroke();
        }
        ctx.fillStyle = '#d4793c';
        ctx.beginPath();
        ctx.arc(p.x, p.y - 58, 3, 0, U.TAU);
        ctx.fill();
        const blink = (Math.sin(performance.now() / 480) + 1) / 2;
        ctx.fillStyle = `rgba(255,120,50,${0.25 + blink * 0.6})`;
        ctx.beginPath();
        ctx.arc(p.x, p.y - 58, 7 + blink * 3, 0, U.TAU);
        ctx.fill();
      } else if (p.type === 'generator') {
        ctx.fillStyle = 'rgba(3,5,3,0.35)';
        ctx.fillRect(p.x - 20, p.y - 12, 48, 38);
        ctx.fillStyle = '#4e523f';
        ctx.fillRect(p.x - 24, p.y - 18, 48, 36);
        ctx.fillStyle = '#33372b';
        ctx.fillRect(p.x - 18, p.y - 12, 36, 24);
        ctx.fillStyle = '#c08e42';
        for (let i = 0; i < 4; i++) ctx.fillRect(p.x - 14 + i * 8, p.y + 2, 4, 8);
        ctx.strokeStyle = '#25291f';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(p.x + 24, p.y - 10);
        ctx.lineTo(p.x + 36, p.y - 10);
        ctx.lineTo(p.x + 36, p.y + 4);
        ctx.stroke();
      } else if (p.type === 'barrel') {
        ctx.fillStyle = 'rgba(3,5,3,0.35)';
        ctx.beginPath();
        ctx.ellipse(p.x + 4, p.y + 6, 13, 8, 0.2, 0, U.TAU);
        ctx.fill();
        ctx.fillStyle = '#525d3d';
        ctx.beginPath();
        ctx.arc(p.x, p.y, 12, 0, U.TAU);
        ctx.fill();
        ctx.strokeStyle = '#2e3524';
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(p.x, p.y, 8, 0, U.TAU); ctx.stroke();
      } else if (p.type === 'crate') {
        ctx.fillStyle = 'rgba(3,5,3,0.32)';
        ctx.fillRect(p.x - 10, p.y - 8, 32, 28);
        ctx.fillStyle = '#5e5637';
        ctx.fillRect(p.x - 14, p.y - 14, 28, 26);
        ctx.strokeStyle = '#38331f';
        ctx.lineWidth = 2;
        ctx.strokeRect(p.x - 14, p.y - 14, 28, 26);
        ctx.beginPath();
        ctx.moveTo(p.x - 14, p.y - 14); ctx.lineTo(p.x + 14, p.y + 12);
        ctx.stroke();
      } else if (p.type === 'flag') {
        ctx.strokeStyle = '#4d5141';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.moveTo(p.x, p.y + 12); ctx.lineTo(p.x, p.y - 64); ctx.stroke();
        const wave = Math.sin(performance.now() / 380) * 5;
        ctx.fillStyle = 'rgba(169,93,43,0.85)';
        ctx.beginPath();
        ctx.moveTo(p.x, p.y - 64);
        ctx.lineTo(p.x + 30 + wave, p.y - 54);
        ctx.lineTo(p.x, p.y - 40);
        ctx.closePath();
        ctx.fill();
        ctx.fillStyle = 'rgba(230,213,164,0.8)';
        ctx.fillRect(p.x + 6, p.y - 57, 4, 4);
      }
    }

    drawBaseStructures(ctx, view) {
      const b = this.base;
      if (b.x + b.r < view.left || b.x - b.r > view.right || b.y + b.r < view.top || b.y - b.r > view.bottom) return;
      // lều
      for (const t of b.tents) {
        ctx.fillStyle = 'rgba(3,5,3,0.35)';
        ctx.beginPath();
        ctx.ellipse(t.x + 6, t.y + t.h * 0.32, t.w * 0.55, t.h * 0.4, 0.2, 0, U.TAU);
        ctx.fill();
        ctx.fillStyle = '#4f5137';
        ctx.beginPath();
        ctx.moveTo(t.x, t.y + t.h / 2);
        ctx.lineTo(t.x + t.w / 2, t.y - t.h / 2);
        ctx.lineTo(t.x + t.w, t.y + t.h / 2);
        ctx.closePath();
        ctx.fill();
        ctx.strokeStyle = 'rgba(28,30,21,0.7)';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(t.x + t.w / 2, t.y - t.h / 2);
        ctx.lineTo(t.x + t.w / 2, t.y + t.h / 2);
        ctx.stroke();
        ctx.fillStyle = 'rgba(18,21,14,0.7)';
        ctx.beginPath();
        ctx.moveTo(t.x + t.w / 2 - 12, t.y + t.h / 2);
        ctx.lineTo(t.x + t.w / 2, t.y + 4);
        ctx.lineTo(t.x + t.w / 2 + 12, t.y + t.h / 2);
        ctx.closePath();
        ctx.fill();
        ctx.fillStyle = 'rgba(191,151,90,0.2)';
        ctx.fillRect(t.x + 5, t.y + t.h / 2 - 5, t.w - 10, 4);
      }

      // bàn chỉ huy
      const c = b.command;
      ctx.fillStyle = 'rgba(3,5,3,0.4)';
      ctx.fillRect(c.x - 48, c.y - 18, 100, 54);
      ctx.fillStyle = '#5a5137';
      ctx.fillRect(c.x - 52, c.y - 26, 104, 50);
      ctx.fillStyle = '#6b6041';
      ctx.fillRect(c.x - 52, c.y - 26, 104, 9);
      ctx.fillStyle = '#2f382a';
      ctx.fillRect(c.x - 42, c.y - 16, 40, 26);
      ctx.strokeStyle = 'rgba(180,160,104,0.35)';
      ctx.lineWidth = 1;
      for (let i = 0; i < 4; i++) {
        ctx.beginPath();
        ctx.moveTo(c.x - 38, c.y - 12 + i * 5);
        ctx.lineTo(c.x - 8, c.y - 12 + i * 5);
        ctx.stroke();
      }
      ctx.fillStyle = '#3d4436';
      ctx.fillRect(c.x + 6, c.y - 17, 18, 22);
      ctx.fillStyle = '#c5883e';
      ctx.fillRect(c.x + 9, c.y - 14, 4, 3);
      ctx.fillRect(c.x + 16, c.y - 14, 4, 3);
      ctx.strokeStyle = '#5d624d';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(c.x + 42, c.y - 24);
      ctx.lineTo(c.x + 42, c.y - 70);
      ctx.stroke();
      ctx.fillStyle = '#cc7c3e';
      ctx.beginPath();
      ctx.arc(c.x + 42, c.y - 72, 4, 0, U.TAU);
      ctx.fill();

      // lửa trại
      const f = b.fire;
      ctx.fillStyle = '#2d2d24';
      ctx.beginPath();
      ctx.ellipse(f.x, f.y, 26, 16, 0, 0, U.TAU);
      ctx.fill();
      for (let i = 0; i < 6; i++) {
        const a = (i / 6) * U.TAU;
        ctx.fillStyle = '#4d4938';
        ctx.beginPath();
        ctx.arc(f.x + Math.cos(a) * 20, f.y + Math.sin(a) * 12, 5, 0, U.TAU);
        ctx.fill();
      }
      const t = performance.now() / 1000;
      for (let i = 0; i < 4; i++) {
        const flick = Math.sin(t * 7 + i * 1.7) * 4;
        ctx.fillStyle = i % 2 ? 'rgba(255,171,69,0.85)' : 'rgba(255,110,40,0.75)';
        ctx.beginPath();
        ctx.moveTo(f.x - 9 + i * 5, f.y + 5);
        ctx.quadraticCurveTo(f.x - 5 + i * 5 + flick, f.y - 18 - i * 2, f.x + i * 4, f.y - 24 - i * 3);
        ctx.quadraticCurveTo(f.x + 5 + i * 4, f.y - 10, f.x + 4 + i * 5, f.y + 5);
        ctx.fill();
      }
    }

    // ============================================================
    //  VẬT TƯ
    // ============================================================
    drawLoot(ctx, loot, nearby) {
      if (loot.x < -100 || loot.x > this.size + 100) return;
      const t = performance.now() / 1000;
      ctx.save();
      if (loot.weaponCache && !loot.opened) {
        const pulse = 0.5 + Math.sin(t * 2.2 + loot.phase) * 0.5;
        const g = ctx.createLinearGradient(loot.x, loot.y - 140, loot.x, loot.y);
        g.addColorStop(0, 'rgba(255,171,69,0)');
        g.addColorStop(1, `rgba(255,171,69,${0.14 + pulse * 0.07})`);
        ctx.fillStyle = g;
        ctx.fillRect(loot.x - 18, loot.y - 140, 36, 140);
      }
      ctx.fillStyle = 'rgba(3,5,3,0.4)';
      ctx.beginPath();
      ctx.ellipse(loot.x + 4, loot.y + 7, 20, 9, 0, 0, U.TAU);
      ctx.fill();

      if (loot.type === 'crate') {
        ctx.fillStyle = loot.opened ? '#3e3a29' : '#665b38';
        ctx.fillRect(loot.x - 15, loot.y - 13, 30, 26);
        ctx.strokeStyle = loot.opened ? '#282619' : '#3d3520';
        ctx.lineWidth = 2;
        ctx.strokeRect(loot.x - 15, loot.y - 13, 30, 26);
        if (!loot.opened) {
          ctx.beginPath();
          ctx.moveTo(loot.x - 15, loot.y - 13); ctx.lineTo(loot.x + 15, loot.y + 13);
          ctx.moveTo(loot.x + 15, loot.y - 13); ctx.lineTo(loot.x - 15, loot.y + 13);
          ctx.stroke();
          ctx.fillStyle = 'rgba(198,167,103,0.5)';
          ctx.fillRect(loot.x - 15, loot.y - 2, 30, 3);
        } else {
          ctx.fillStyle = '#252217';
          ctx.fillRect(loot.x - 10, loot.y - 8, 20, 16);
        }
      } else if (loot.type === 'weapon') {
        const pulse = 0.5 + Math.sin(t * 2.4 + loot.phase) * 0.5;
        ctx.fillStyle = loot.opened ? '#4a4230' : '#735c34';
        ctx.fillRect(loot.x - 21, loot.y - 15, 42, 30);
        ctx.strokeStyle = loot.opened ? '#6d5c3a' : '#c8903e';
        ctx.lineWidth = 2;
        ctx.strokeRect(loot.x - 21, loot.y - 15, 42, 30);
        if (!loot.opened) {
          ctx.fillStyle = `rgba(255,180,80,${0.35 + pulse * 0.25})`;
          ctx.fillRect(loot.x - 21, loot.y - 1, 42, 3);
          ctx.font = 'bold 13px var(--mono), monospace';
          ctx.fillStyle = '#ffc477';
          ctx.textAlign = 'center';
          ctx.fillText('⌖', loot.x, loot.y + 1);
          ctx.textAlign = 'left';
        }
      } else if (loot.type === 'duffel') {
        ctx.fillStyle = loot.opened ? '#2d3528' : '#45523a';
        ctx.beginPath();
        ctx.ellipse(loot.x, loot.y, 19, 11, 0.1, 0, U.TAU);
        ctx.fill();
        ctx.strokeStyle = '#20281b';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(loot.x - 14, loot.y);
        ctx.lineTo(loot.x + 14, loot.y);
        ctx.stroke();
        if (!loot.opened) {
          ctx.fillStyle = '#8b7a4b';
          ctx.fillRect(loot.x - 4, loot.y - 2, 8, 5);
        }
      } else if (loot.type === 'corpse') {
        ctx.fillStyle = '#3c3a2c';
        ctx.beginPath();
        ctx.ellipse(loot.x, loot.y, 18, 9, 0.5, 0, U.TAU);
        ctx.fill();
        ctx.fillStyle = '#6a5c45';
        ctx.beginPath();
        ctx.arc(loot.x + 13, loot.y - 6, 5, 0, U.TAU);
        ctx.fill();
        if (!loot.opened) {
          ctx.fillStyle = 'rgba(168,57,42,0.7)';
          ctx.fillRect(loot.x - 18, loot.y + 5, 26, 3);
        }
      } else if (loot.type === 'locker') {
        ctx.fillStyle = loot.opened ? '#2d3b31' : '#3f5948';
        ctx.fillRect(loot.x - 16, loot.y - 14, 32, 28);
        ctx.strokeStyle = '#243a2b';
        ctx.lineWidth = 2;
        ctx.strokeRect(loot.x - 16, loot.y - 14, 32, 28);
        ctx.fillStyle = '#a8be7a';
        ctx.fillRect(loot.x - 2, loot.y - 5, 5, 10);
      } else {
        // supply
        ctx.fillStyle = loot.opened ? '#3b3d2a' : '#4f5c3b';
        ctx.fillRect(loot.x - 19, loot.y - 14, 38, 28);
        ctx.fillStyle = '#2d3724';
        ctx.fillRect(loot.x - 19, loot.y - 14, 38, 8);
        ctx.fillStyle = '#c7a34f';
        ctx.fillRect(loot.x - 6, loot.y - 2, 12, 4);
      }

      if (nearby && !loot.opened) {
        const pulse = 0.5 + Math.sin(t * 3) * 0.5;
        ctx.strokeStyle = `rgba(255,171,69,${0.35 + pulse * 0.35})`;
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(loot.x, loot.y, 26 + pulse * 3, 0, U.TAU);
        ctx.stroke();
      }
      ctx.restore();
    }

    // ============================================================
    //  BẢN ĐỒ NHỎ
    // ============================================================
    drawMinimap(ctx, game) {
      const W = 220, H = 220;
      const s = W / this.size;
      ctx.clearRect(0, 0, W, H);
      ctx.fillStyle = '#080d09';
      ctx.fillRect(0, 0, W, H);

      // vùng đã khám phá
      const cell = 100;
      for (const key of this.explored) {
        const [cx, cy] = key.split(',').map(Number);
        if (cx < 0 || cy < 0 || cx * cell > this.size || cy * cell > this.size) continue;
        ctx.fillStyle = '#1b2419';
        ctx.fillRect(cx * cell * s, cy * cell * s, cell * s + 0.5, cell * s + 0.5);
      }

      // đường
      ctx.strokeStyle = 'rgba(121,116,86,0.35)';
      ctx.lineWidth = 2.4;
      const roads = this.roadRects();
      for (const r of roads) {
        if (r.w > r.h) {
          ctx.beginPath(); ctx.moveTo(r.x * s, (r.y + r.h / 2) * s); ctx.lineTo((r.x + r.w) * s, (r.y + r.h / 2) * s); ctx.stroke();
        } else {
          ctx.beginPath(); ctx.moveTo((r.x + r.w / 2) * s, r.y * s); ctx.lineTo((r.x + r.w / 2) * s, (r.y + r.h) * s); ctx.stroke();
        }
      }

      // nhà
      for (const b of this.buildings) {
        if (!this.isExplored(b.x + b.w / 2, b.y + b.h / 2)) continue;
        ctx.fillStyle = 'rgba(117,122,99,0.22)';
        ctx.fillRect(b.x * s, b.y * s, b.w * s, b.h * s);
        ctx.strokeStyle = 'rgba(144,149,119,0.28)';
        ctx.lineWidth = 0.7;
        ctx.strokeRect(b.x * s, b.y * s, b.w * s, b.h * s);
      }

      // vật tư đã khám phá
      for (const l of this.loots) {
        if (l.opened) continue;
        if (!this.isExplored(l.x, l.y)) continue;
        ctx.fillStyle = l.weaponCache ? '#ffab45' : 'rgba(201,165,92,0.65)';
        ctx.beginPath();
        ctx.arc(l.x * s, l.y * s, l.weaponCache ? 2.6 : 1.4, 0, U.TAU);
        ctx.fill();
      }

      // công trình
      for (const st of game.structures) {
        ctx.fillStyle = st.kind === 'turret' ? '#72c4c1' : 'rgba(137,177,124,0.8)';
        ctx.fillRect(st.x * s - 1, st.y * s - 1, 2.4, 2.4);
      }

      // địch
      for (const e of game.enemies) {
        if (e.dead) continue;
        if (U.dist(e.x, e.y, game.player.x, game.player.y) > 1500 && !game.nightActive) continue;
        ctx.fillStyle = e.type === 'boss' ? '#ff6b3d' : '#cf5841';
        const rr = e.type === 'boss' ? 3.4 : 1.8;
        ctx.beginPath();
        ctx.arc(e.x * s, e.y * s, rr, 0, U.TAU);
        ctx.fill();
      }

      // lính
      for (const sld of game.soldiers) {
        if (sld.dead) continue;
        ctx.fillStyle = '#8fce80';
        ctx.beginPath(); ctx.arc(sld.x * s, sld.y * s, 1.8, 0, U.TAU); ctx.fill();
      }

      // căn cứ
      ctx.strokeStyle = 'rgba(255,171,69,0.75)';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.arc(this.base.x * s, this.base.y * s, this.base.r * s, 0, U.TAU);
      ctx.stroke();
      ctx.fillStyle = 'rgba(255,171,69,0.28)';
      ctx.beginPath(); ctx.arc(this.base.x * s, this.base.y * s, 3, 0, U.TAU); ctx.fill();

      // người chơi
      const p = game.player;
      ctx.save();
      ctx.translate(p.x * s, p.y * s);
      ctx.rotate(p.aimAngle + Math.PI / 2);
      ctx.fillStyle = '#d6e7a0';
      ctx.beginPath();
      ctx.moveTo(0, -4.5);
      ctx.lineTo(3.2, 3.4);
      ctx.lineTo(0, 2);
      ctx.lineTo(-3.2, 3.4);
      ctx.closePath();
      ctx.fill();
      ctx.restore();

      // khung nhìn
      const vw = game.W / game.cam.zoom * s;
      const vh = game.H / game.cam.zoom * s;
      ctx.strokeStyle = 'rgba(230,224,200,0.16)';
      ctx.lineWidth = 0.8;
      ctx.strokeRect(game.cam.x * s - vw / 2, game.cam.y * s - vh / 2, vw, vh);

      ctx.strokeStyle = 'rgba(207,224,189,0.15)';
      ctx.lineWidth = 1;
      ctx.strokeRect(0.5, 0.5, W - 1, H - 1);
    }
  }

  TT.World = World;
})();

/* ============================================================
   entities.js — người chơi, dị biến, lính, đạn, công trình
   ============================================================ */
(function () {
  'use strict';
  const U = TT.U;
  const TAU = U.TAU;

  /* ============================================================
     HIỆU ỨNG
     ============================================================ */
  class Particle {
    constructor(o) {
      this.x = o.x; this.y = o.y;
      this.vx = o.vx || 0; this.vy = o.vy || 0;
      this.life = o.life || 0.5; this.maxLife = this.life;
      this.size = o.size || 3;
      this.color = o.color || '#ffab45';
      this.drag = o.drag ?? 0.9;
      this.glow = o.glow || false;
      this.shrink = o.shrink !== false;
      this.gravity = o.gravity || 0;
      this.type = o.type || 'dot';
      this.rot = o.rot || 0;
      this.spin = o.spin || 0;
    }
    update(dt) {
      this.x += this.vx * dt;
      this.y += this.vy * dt;
      this.vx *= Math.pow(this.drag, dt * 60);
      this.vy *= Math.pow(this.drag, dt * 60);
      this.vy += this.gravity * dt;
      this.rot += this.spin * dt;
      this.life -= dt;
    }
    draw(ctx) {
      const a = U.clamp(this.life / this.maxLife, 0, 1);
      const s = this.shrink ? this.size * (0.35 + a * 0.65) : this.size;
      ctx.globalAlpha = a;
      if (this.glow) ctx.globalCompositeOperation = 'lighter';
      ctx.fillStyle = this.color;
      if (this.type === 'spark') {
        ctx.save();
        ctx.translate(this.x, this.y);
        ctx.rotate(Math.atan2(this.vy, this.vx));
        ctx.fillRect(-s * 2, -s * 0.35, s * 4, s * 0.7);
        ctx.restore();
      } else if (this.type === 'shell') {
        ctx.save();
        ctx.translate(this.x, this.y);
        ctx.rotate(this.rot);
        ctx.fillRect(-2, -1, 4, 2);
        ctx.restore();
      } else {
        ctx.beginPath();
        ctx.arc(this.x, this.y, Math.max(0.3, s), 0, TAU);
        ctx.fill();
      }
      ctx.globalCompositeOperation = 'source-over';
      ctx.globalAlpha = 1;
    }
  }

  class FloatText {
    constructor(x, y, text, color = '#ffd28a', size = 12) {
      this.x = x; this.y = y; this.text = text; this.color = color;
      this.life = 0.95; this.maxLife = 0.95; this.size = size;
      this.vy = -38; this.vx = U.rand(-8, 8);
    }
    update(dt) {
      this.life -= dt;
      this.y += this.vy * dt;
      this.x += this.vx * dt;
      this.vy *= 0.96;
    }
    draw(ctx) {
      const a = U.clamp(this.life / this.maxLife, 0, 1);
      ctx.globalAlpha = Math.min(1, a * 1.6);
      ctx.font = `800 ${this.size}px ui-monospace, Consolas, monospace`;
      ctx.textAlign = 'center';
      ctx.fillStyle = 'rgba(0,0,0,0.55)';
      ctx.fillText(this.text, this.x + 1, this.y + 1);
      ctx.fillStyle = this.color;
      ctx.fillText(this.text, this.x, this.y);
      ctx.textAlign = 'left';
      ctx.globalAlpha = 1;
    }
  }

  /* ============================================================
     ĐẠN
     ============================================================ */
  class Bullet {
    constructor(game, o) {
      this.game = game;
      this.x = o.x; this.y = o.y;
      this.vx = o.vx; this.vy = o.vy;
      this.damage = o.damage || 10;
      this.team = o.team || 'player';
      this.life = o.life || 1.4;
      this.size = o.size || 2.4;
      this.color = o.color || '#ffd08a';
      this.acid = o.acid || false;
      this.dead = false;
      this.trail = [];
      this.pierce = o.pierce || 0;
    }

    update(dt) {
      if (this.dead) return;
      this.life -= dt;
      if (this.life <= 0) { this.dead = true; return; }

      this.trail.push({ x: this.x, y: this.y });
      if (this.trail.length > 5) this.trail.shift();

      const speed = Math.hypot(this.vx, this.vy);
      const steps = Math.max(1, Math.ceil((speed * dt) / 12));
      const sx = (this.vx * dt) / steps;
      const sy = (this.vy * dt) / steps;

      for (let i = 0; i < steps; i++) {
        this.x += sx;
        this.y += sy;

        // địa hình
        for (const o of this.game.world.obstacles) {
          if (!o.solid) continue;
          if (this.x > o.x && this.x < o.x + o.w && this.y > o.y && this.y < o.y + o.h) {
            if (o.explosive) this.game.explodeBarrel(o);
            else this.game.bulletImpact(this.x, this.y, this.acid);
            this.dead = true;
            return;
          }
        }
        // công trình (đạn địch)
        if (this.team === 'enemy') {
          for (const st of this.game.structures) {
            if (st.dead) continue;
            if (this.x > st.x - st.w / 2 && this.x < st.x + st.w / 2 && this.y > st.y - st.h / 2 && this.y < st.y + st.h / 2) {
              st.takeDamage(this.damage * 0.7, this.game);
              this.game.bulletImpact(this.x, this.y, this.acid);
              this.dead = true;
              return;
            }
          }
        }

        if (this.team === 'enemy') {
          const p = this.game.player;
          if (!p.dead && U.dist(this.x, this.y, p.x, p.y) < 15 + this.size) {
            p.takeDamage(this.damage, this.game);
            this.game.bulletImpact(this.x, this.y, this.acid);
            this.dead = true;
            return;
          }
          for (const s of this.game.soldiers) {
            if (s.dead) continue;
            if (U.dist(this.x, this.y, s.x, s.y) < 14 + this.size) {
              s.takeDamage(this.damage, this.game);
              this.game.bulletImpact(this.x, this.y, this.acid);
              this.dead = true;
              return;
            }
          }
        } else {
          for (const e of this.game.enemies) {
            if (e.dead) continue;
            const rr = e.r + this.size;
            if (U.dist2(this.x, this.y, e.x, e.y) < rr * rr) {
              e.takeDamage(this.damage, this.game, this.vx, this.vy);
              this.game.bulletImpact(this.x, this.y, this.acid, true);
              if (this.pierce > 0) this.pierce--;
              else { this.dead = true; return; }
            }
          }
        }
      }
      if (this.x < 0 || this.y < 0 || this.x > this.game.world.size || this.y > this.game.world.size) this.dead = true;
    }

    draw(ctx) {
      const col = this.acid ? '#a9e05a' : this.color;
      ctx.globalCompositeOperation = 'lighter';
      ctx.strokeStyle = col;
      ctx.lineWidth = this.size * 0.85;
      ctx.globalAlpha = 0.55;
      ctx.beginPath();
      if (this.trail.length > 1) {
        ctx.moveTo(this.trail[0].x, this.trail[0].y);
        for (let i = 1; i < this.trail.length; i++) ctx.lineTo(this.trail[i].x, this.trail[i].y);
        ctx.lineTo(this.x, this.y);
      } else {
        ctx.moveTo(this.x - this.vx * 0.014, this.y - this.vy * 0.014);
        ctx.lineTo(this.x, this.y);
      }
      ctx.stroke();
      ctx.globalAlpha = 1;
      ctx.fillStyle = col;
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.size, 0, TAU);
      ctx.fill();
      if (this.acid) {
        ctx.globalAlpha = 0.35;
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size * 2.6, 0, TAU);
        ctx.fill();
        ctx.globalAlpha = 1;
      }
      ctx.globalCompositeOperation = 'source-over';
    }
  }

  /* ============================================================
     NGƯỜI CHƠI
     ============================================================ */
  class Player {
    constructor(game) {
      this.game = game;
      this.x = game.world.base.spawn.x;
      this.y = game.world.base.spawn.y;
      this.r = 15;
      this.hp = 100;
      this.maxHp = 100;
      this.stamina = 100;
      this.maxStamina = 100;
      this.level = 1;
      this.xp = 0;
      this.xpNext = 100;
      this.speed = 238;
      this.angle = 0;
      this.aimAngle = -Math.PI / 2;
      this.moveAngle = -Math.PI / 2;
      this.moving = false;
      this.walkPhase = 0;
      this.dashTimer = 0;
      this.dashCd = 0;
      this.dashDir = { x: 0, y: -1 };
      this.invuln = 0;
      this.recoil = 0;
      this.muzzle = 0;
      this.swingTimer = 0;
      this.swingDir = 0;
      this.reloadTimer = 0;
      this.reloadTotal = 0;
      this.weapons = TT.WEAPONS.map(w => ({ ...w, mag: w.type === 'gun' ? w.magSize : 0, owned: w.owned }));
      this.current = 1;
      this.fireCd = 0;
      this.dead = false;
      this.footstep = 0;
      this.healFlash = 0;
      this.lastDamageAt = 0;
      this.kills = 0;
    }

    get weapon() { return this.weapons[this.current]; }

    update(dt, input) {
      if (this.dead) return;
      this.fireCd = Math.max(0, this.fireCd - dt);
      this.dashCd = Math.max(0, this.dashCd - dt);
      this.invuln = Math.max(0, this.invuln - dt);
      this.muzzle = Math.max(0, this.muzzle - dt);
      this.recoil = Math.max(0, this.recoil - dt * 8);
      this.swingTimer = Math.max(0, this.swingTimer - dt);
      this.healFlash = Math.max(0, this.healFlash - dt);

      // nạp đạn
      if (this.reloadTimer > 0) {
        this.reloadTimer -= dt;
        if (this.reloadTimer <= 0) this.finishReload();
      }

      // lướt
      if (this.dashTimer > 0) {
        this.dashTimer -= dt;
        this.x += this.dashDir.x * 780 * dt;
        this.y += this.dashDir.y * 780 * dt;
        this.game.resolveCircle(this, this.r);
        if (Math.random() < 0.7) {
          this.game.addParticle({
            x: this.x + U.rand(-6, 6), y: this.y + U.rand(-4, 4),
            vx: U.rand(-20, 20), vy: U.rand(-20, 20), life: 0.35, size: 4,
            color: 'rgba(165,178,139,0.4)', drag: 0.9,
          });
        }
        this.stamina = Math.max(0, this.stamina - 12 * dt);
      } else {
        let mx = input.move.x, my = input.move.y;
        const len = Math.hypot(mx, my);
        this.moving = len > 0.08;
        if (this.moving) {
          mx /= len; my /= len;
          this.moveAngle = Math.atan2(my, mx);
          const sprinting = input.sprint && this.stamina > 2;
          const sp = this.speed * (sprinting ? 1.48 : 1) * (this.reloadTimer > 0 ? 0.78 : 1);
          this.x += mx * sp * dt;
          this.y += my * sp * dt;
          this.walkPhase += dt * (sprinting ? 15 : 10);
          this.game.resolveCircle(this, this.r);
          if (sprinting) this.stamina = Math.max(0, this.stamina - 17 * dt);
          this.footstep += dt;
          if (this.footstep > (sprinting ? 0.22 : 0.32)) {
            this.footstep = 0;
            this.game.addParticle({
              x: this.x - mx * 8 + U.rand(-4, 4), y: this.y + 8,
              vx: U.rand(-12, 12), vy: U.rand(-6, 6), life: 0.4,
              size: 4, color: 'rgba(116,109,80,0.32)', drag: 0.88,
            });
          }
        } else {
          this.walkPhase += dt * 2;
        }
        if (!input.sprint || !this.moving) this.stamina = Math.min(this.maxStamina, this.stamina + 21 * dt);
      }

      // biên bản đồ
      this.x = U.clamp(this.x, 80, this.game.world.size - 80);
      this.y = U.clamp(this.y, 80, this.game.world.size - 80);
    }

    startReload() {
      const w = this.weapon;
      if (w.type !== 'gun' || this.reloadTimer > 0) return;
      const ammo = this.game.ammo[w.ammoType];
      if (w.mag >= w.magSize || ammo <= 0) {
        if (ammo <= 0 && w.mag <= 0) {
          this.game.toast(`HẾT ${TT.AMMO[w.ammoType].name}`, 'bad');
          TT.audio.empty();
        }
        return;
      }
      this.reloadTotal = w.reloadTime * (1 - 0.06 * (w.level - 1));
      this.reloadTimer = this.reloadTotal;
      TT.audio.reload();
    }

    finishReload() {
      const w = this.weapon;
      if (!w || w.type !== 'gun') return;
      const ammo = this.game.ammo[w.ammoType];
      const need = w.magSize - w.mag;
      const take = Math.min(need, ammo);
      w.mag += take;
      this.game.ammo[w.ammoType] -= take;
      this.reloadTimer = 0;
      this.reloadTotal = 0;
    }

    switchWeapon(index) {
      if (index === this.current) return;
      const w = this.weapons[index];
      if (!w || !w.owned) {
        this.game.toast('VŨ KHÍ CHƯA ĐƯỢC MỞ KHÓA', 'bad');
        TT.audio.error();
        return;
      }
      this.current = index;
      this.reloadTimer = 0;
      this.game.ui.refreshWeapons();
      TT.audio.click();
    }

    heal(amount, silent = false) {
      const before = this.hp;
      this.hp = Math.min(this.maxHp, this.hp + amount);
      const got = this.hp - before;
      if (got > 0) {
        this.healFlash = 0.5;
        this.game.addFloatText(this.x, this.y - 26, `+${Math.round(got)}`, '#9fe08c', 12);
        if (!silent) TT.audio.heal();
      }
      return got;
    }

    takeDamage(amount, game) {
      if (this.invuln > 0 || this.dead) return;
      this.hp -= amount;
      this.invuln = 0.36;
      this.lastDamageAt = performance.now();
      game.onPlayerHurt(amount);
      TT.audio.hurt();
      game.addFloatText(this.x, this.y - 28, `-${Math.round(amount)}`, '#ff8a70', 13);
      for (let i = 0; i < 8; i++) {
        game.addParticle({
          x: this.x, y: this.y, vx: U.rand(-100, 100), vy: U.rand(-100, 100),
          life: U.rand(0.25, 0.5), size: U.rand(1.4, 3), color: 'rgba(165,43,30,0.8)',
          type: 'spark', drag: 0.9, glow: false,
        });
      }
      if (this.hp <= 0) {
        this.hp = 0;
        this.dead = true;
        game.onPlayerDeath();
      }
    }

    draw(ctx) {
      const t = performance.now() / 1000;
      const flicker = this.invuln > 0 && Math.floor(this.invuln * 24) % 2 === 0;
      ctx.save();
      ctx.translate(this.x, this.y);

      // bóng
      ctx.fillStyle = 'rgba(2,4,2,0.42)';
      ctx.beginPath();
      ctx.ellipse(3, 10, 17, 8, 0, 0, TAU);
      ctx.fill();

      // chân
      const swing = this.moving ? Math.sin(this.walkPhase) * 7 : 0;
      ctx.save();
      ctx.rotate(this.moveAngle);
      ctx.strokeStyle = '#2c3428';
      ctx.lineCap = 'round';
      ctx.lineWidth = 7;
      ctx.beginPath();
      ctx.moveTo(-2, -6); ctx.lineTo(3 + swing, -8);
      ctx.moveTo(-2, 6); ctx.lineTo(3 - swing, 8);
      ctx.stroke();
      ctx.strokeStyle = '#1e241c';
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(3 + swing, -8); ctx.lineTo(5 + swing, -9);
      ctx.moveTo(3 - swing, 8); ctx.lineTo(5 - swing, 9);
      ctx.stroke();
      ctx.restore();

      // thân xoay theo hướng ngắm
      ctx.save();
      ctx.rotate(this.aimAngle);
      // ba lô
      ctx.fillStyle = '#383d2c';
      ctx.beginPath();
      ctx.roundRect(-16, -7, 10, 14, 3);
      ctx.fill();
      ctx.fillStyle = '#454b36';
      ctx.fillRect(-14, -5, 5, 10);
      // thân
      if (flicker) ctx.globalAlpha = 0.65;
      ctx.fillStyle = '#566442';
      ctx.beginPath();
      ctx.ellipse(0, 0, 11, 13, 0, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = '#2f3928';
      ctx.lineWidth = 1.6;
      ctx.stroke();
      // giáp vai
      ctx.fillStyle = '#65704d';
      ctx.beginPath();
      ctx.ellipse(-2, -10, 5, 4, 0.3, 0, TAU);
      ctx.fill();
      ctx.beginPath();
      ctx.ellipse(-2, 10, 5, 4, -0.3, 0, TAU);
      ctx.fill();
      // tay
      ctx.strokeStyle = '#a37850';
      ctx.lineWidth = 3.5;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(3, -8); ctx.lineTo(14, -5);
      ctx.moveTo(3, 8); ctx.lineTo(14, 5);
      ctx.stroke();
      // đầu
      ctx.fillStyle = '#bd8c60';
      ctx.beginPath();
      ctx.arc(3, 0, 7, 0, TAU);
      ctx.fill();
      ctx.fillStyle = '#252d23';
      ctx.beginPath();
      ctx.arc(1.5, 0, 7.2, 1.6, 4.7);
      ctx.fill();
      // vũ khí
      this.drawWeapon(ctx, t);
      // tay cầm súng
      if (this.weapon.type !== 'melee') {
        ctx.strokeStyle = '#a37850';
        ctx.lineWidth = 3.2;
        ctx.beginPath();
        ctx.moveTo(10, 5); ctx.lineTo(20, 3);
        ctx.stroke();
      }
      ctx.restore();

      // hiệu ứng cận chiến
      if (this.swingTimer > 0) {
        const prog = 1 - this.swingTimer / 0.18;
        ctx.strokeStyle = `rgba(255,226,170,${0.55 * (1 - prog)})`;
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(0, 0, 42, this.swingDir - 0.9 + prog * 1.8, this.swingDir - 0.5 + prog * 1.8);
        ctx.stroke();
      }

      // nạp đạn
      if (this.reloadTimer > 0) {
        const p = 1 - this.reloadTimer / this.reloadTotal;
        ctx.strokeStyle = 'rgba(255,171,69,0.18)';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(0, 0, 26, -Math.PI / 2, TAU - Math.PI / 2);
        ctx.stroke();
        ctx.strokeStyle = '#ffab45';
        ctx.beginPath();
        ctx.arc(0, 0, 26, -Math.PI / 2, -Math.PI / 2 + TAU * p);
        ctx.stroke();
      }

      // hồi máu
      if (this.healFlash > 0) {
        ctx.strokeStyle = `rgba(150,224,120,${this.healFlash * 0.7})`;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(0, 0, 24 + (0.5 - this.healFlash) * 30, 0, TAU);
        ctx.stroke();
      }
      ctx.restore();
    }

    drawWeapon(ctx, t) {
      const w = this.weapon;
      const kick = this.recoil * 3;
      ctx.save();
      ctx.translate(10 - kick, 3);
      if (w.type === 'melee') {
        ctx.rotate(-0.3);
        ctx.fillStyle = '#4b3b28';
        ctx.fillRect(0, -2, 10, 4);
        ctx.fillStyle = '#c4c6b6';
        ctx.beginPath();
        ctx.moveTo(10, -2.4);
        ctx.lineTo(33, -1.6);
        ctx.lineTo(36, 0);
        ctx.lineTo(33, 1.6);
        ctx.lineTo(10, 2.4);
        ctx.closePath();
        ctx.fill();
        ctx.fillStyle = 'rgba(255,255,255,0.35)';
        ctx.fillRect(14, -1, 18, 0.8);
      } else if (w.id === 'pistol') {
        ctx.fillStyle = '#2b2f2a';
        ctx.fillRect(0, -3, 17, 6);
        ctx.fillStyle = '#454b40';
        ctx.fillRect(2, -4, 11, 2);
        ctx.fillStyle = '#1e211d';
        ctx.fillRect(2, 2, 5, 7);
        ctx.fillStyle = '#757b68';
        ctx.fillRect(15, -1.4, 4, 2.8);
      } else if (w.id === 'shotgun') {
        ctx.fillStyle = '#4a3826';
        ctx.fillRect(-4, -2.5, 15, 5);
        ctx.fillStyle = '#33362f';
        ctx.fillRect(9, -2.6, 30, 4);
        ctx.fillStyle = '#55594b';
        ctx.fillRect(12, 1.4, 20, 2.3);
        ctx.fillStyle = '#6b5a3b';
        ctx.fillRect(14, -5, 8, 3);
        ctx.fillStyle = '#2a2c26';
        ctx.fillRect(36, -1.6, 4, 3.2);
      } else if (w.id === 'rifle') {
        ctx.fillStyle = '#3d3f34';
        ctx.fillRect(-6, -2, 16, 4.4);
        ctx.fillStyle = '#55594b';
        ctx.fillRect(8, -2.3, 32, 4.2);
        ctx.fillStyle = '#22251f';
        ctx.fillRect(14, 1.6, 7, 6);
        ctx.fillStyle = '#707966';
        ctx.fillRect(38, -1.6, 7, 2.8);
        ctx.fillStyle = '#2f3229';
        ctx.fillRect(20, -5, 9, 2.4);
      }

      if (this.muzzle > 0) {
        const a = this.muzzle / 0.07;
        ctx.globalCompositeOperation = 'lighter';
        const g = ctx.createRadialGradient(38, 0, 1, 38, 0, 18);
        g.addColorStop(0, `rgba(255,245,190,${a})`);
        g.addColorStop(0.4, `rgba(255,170,60,${a * 0.7})`);
        g.addColorStop(1, 'rgba(255,110,20,0)');
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(38, 0, 18, 0, TAU);
        ctx.fill();
        ctx.globalCompositeOperation = 'source-over';
      }
      ctx.restore();
    }
  }

  /* ============================================================
     DỊ BIẾN
     ============================================================ */
  class Enemy {
    constructor(game, type, x, y, night = 1, wave = false) {
      this.game = game;
      this.type = type;
      this.cfg = TT.ENEMIES[type];
      this.x = x; this.y = y;
      this.r = this.cfg.r;
      this.night = night;
      this.waveEnemy = wave;
      const hpScale = 1 + 0.24 * (night - 1) + (wave ? 0.08 * game.waveNumber : 0);
      this.maxHp = Math.round(this.cfg.hp * hpScale);
      this.hp = this.maxHp;
      this.speed = this.cfg.speed * (1 + 0.035 * (night - 1));
      this.damage = this.cfg.damage * (1 + 0.09 * (night - 1));
      this.xp = this.cfg.xp;
      this.angle = U.rand(0, TAU);
      this.walkPhase = U.rand(0, 6.28);
      this.attackCd = U.rand(0, 0.5);
      this.rangedCd = U.rand(1, 2);
      this.think = 0;
      this.target = null;
      this.targetKind = null;
      this.aggro = false;
      this.flash = 0;
      this.dead = false;
      this.deathTimer = 0;
      this.wanderAngle = U.rand(0, TAU);
      this.wanderTimer = U.rand(1, 3);
      this.retreat = false;
      this.retreatTimer = 0;
      this.stuckTimer = 0;
      this.bloodColor = this.type === 'spitter' ? '#6f9c3e' : '#7a2c22';
      this.hpShow = 0;
      this.spawnAnim = 0.6;
      this.bossRoarCd = 3;
      this.step = 0;
    }

    takeDamage(amount, game, vx = 0, vy = 0) {
      if (this.dead) return;
      this.hp -= amount;
      this.flash = 0.09;
      this.hpShow = 2;
      this.aggro = true;
      const kb = this.type === 'boss' ? 8 : this.type === 'brute' ? 16 : 34;
      this.x += (vx / 1200) * kb;
      this.y += (vy / 1200) * kb;
      game.addFloatText(this.x + U.rand(-6, 6), this.y - this.r - 12, `${Math.round(amount)}`, this.type === 'boss' ? '#ffb069' : '#ffd28a', amount >= 30 ? 14 : 11);
      for (let i = 0; i < 7; i++) {
        game.addParticle({
          x: this.x, y: this.y - 3, vx: U.rand(-130, 130), vy: U.rand(-130, 80),
          life: U.rand(0.25, 0.55), size: U.rand(1.4, 3.4), color: this.bloodColor,
          type: 'spark', drag: 0.9,
        });
      }
      TT.audio.hit();
      if (this.hp <= 0) this.die(game);
    }

    die(game) {
      if (this.dead) return;
      this.dead = true;
      this.deathTimer = 0.8;
      game.onEnemyKilled(this);
      TT.audio.kill();
      game.shake(5, 0.18);
      for (let i = 0; i < (this.type === 'boss' ? 50 : 16); i++) {
        game.addParticle({
          x: this.x, y: this.y, vx: U.rand(-220, 220), vy: U.rand(-220, 220),
          life: U.rand(0.4, 1.1), size: U.rand(2, this.type === 'boss' ? 8 : 4.2),
          color: i % 3 === 0 ? '#2f3a29' : this.bloodColor, drag: 0.9,
        });
      }
      game.addDecal({ type: 'blood', x: this.x, y: this.y, r: this.r * 1.5, rot: U.rand(0, TAU), seed: Math.random() * 99 });
      // rơi vật tư
      if (U.chance(this.type === 'boss' ? 1 : this.type === 'brute' ? 0.5 : 0.16)) {
        game.spawnDrop(this.x, this.y, this.type === 'brute' || this.type === 'boss' ? 'supply' : 'crate');
      }
      if (this.type === 'boss') {
        game.showBanner('MỤC TIÊU BỊ TIÊU DIỆT', 'QUÁI VẬT CHÚA ĐÃ GỤC NGÃ', 'Căn cứ tạm thời an toàn', 3.4);
        game.shake(18, 0.6);
        TT.audio.bossRoar();
      }
    }

    update(dt) {
      if (this.dead) return;
      this.flash = Math.max(0, this.flash - dt);
      this.hpShow = Math.max(0, this.hpShow - dt);
      this.attackCd = Math.max(0, this.attackCd - dt);
      this.rangedCd = Math.max(0, this.rangedCd - dt);
      this.spawnAnim = Math.max(0, this.spawnAnim - dt);
      this.think -= dt;
      this.walkPhase += dt * 7;
      this.bossRoarCd -= dt;

      if (this.retreat) {
        this.retreatTimer -= dt;
        const base = this.game.world.base;
        const a = Math.atan2(this.y - base.y, this.x - base.x);
        this.move(this.x + Math.cos(a) * 160 * dt, this.y + Math.sin(a) * 160 * dt);
        if (this.retreatTimer <= 0) this.dead = true;
        return;
      }

      const game = this.game;
      const p = game.player;

      if (this.think <= 0) {
        this.think = 0.3 + Math.random() * 0.2;
        this.pickTarget();
      }

      let tx = this.x, ty = this.y;
      let distT = 9999;
      if (this.targetKind === 'player' && !p.dead) {
        tx = p.x; ty = p.y; distT = U.dist(this.x, this.y, tx, ty);
      } else if (this.targetKind === 'soldier' && this.target && !this.target.dead) {
        tx = this.target.x; ty = this.target.y; distT = U.dist(this.x, this.y, tx, ty);
      } else if (this.targetKind === 'structure' && this.target && !this.target.dead) {
        tx = this.target.x; ty = this.target.y; distT = U.dist(this.x, this.y, tx, ty) - Math.max(this.target.w, this.target.h) * 0.5;
      } else if (this.targetKind === 'base') {
        tx = game.world.base.x; ty = game.world.base.y; distT = U.dist(this.x, this.y, tx, ty);
      } else {
        // lang thang
        this.wanderTimer -= dt;
        if (this.wanderTimer <= 0) {
          this.wanderTimer = U.rand(2, 5);
          this.wanderAngle = U.rand(0, TAU);
        }
        tx = this.x + Math.cos(this.wanderAngle) * 100;
        ty = this.y + Math.sin(this.wanderAngle) * 100;
        distT = 100;
      }

      const angleTo = Math.atan2(ty - this.y, tx - this.x);
      this.angle += U.angleDiff(this.angle, angleTo) * Math.min(1, dt * 7);

      const attackRange = this.cfg.ranged ? 210 : this.cfg.attackRange + this.r;
      const shouldApproach = distT > attackRange - (this.cfg.ranged ? 40 : 0);
      if (shouldApproach && this.spawnAnim <= 0) {
        const speed = this.speed * (this.waveEnemy ? 1.04 : 1);
        let mx = Math.cos(angleTo), my = Math.sin(angleTo);
        // né vật cản: nếu bị kẹt, thử hướng chéo
        if (this.stuckTimer > 0.4) {
          const side = (this.seedSide || 1);
          mx = Math.cos(angleTo + side * 0.9);
          my = Math.sin(angleTo + side * 0.9);
        }
        // tách bầy
        let sepX = 0, sepY = 0;
        for (const other of game.enemies) {
          if (other === this || other.dead) continue;
          const dx = this.x - other.x, dy = this.y - other.y;
          const d2 = dx * dx + dy * dy;
          const rr = (this.r + other.r + 4);
          if (d2 > 0.01 && d2 < rr * rr) {
            const d = Math.sqrt(d2);
            sepX += (dx / d) * (1 - d / rr);
            sepY += (dy / d) * (1 - d / rr);
          }
        }
        mx += sepX * 1.5; my += sepY * 1.5;
        const ml = Math.hypot(mx, my) || 1;
        const ox = this.x, oy = this.y;
        this.move(this.x + (mx / ml) * speed * dt, this.y + (my / ml) * speed * dt);
        const moved = U.dist(ox, oy, this.x, this.y);
        if (moved < speed * dt * 0.3) this.stuckTimer += dt;
        else this.stuckTimer = Math.max(0, this.stuckTimer - dt * 2);
        if (this.stuckTimer > 0.8) { this.seedSide = (this.seedSide || 1) * -1; this.stuckTimer = 0; }
      } else {
        this.stuckTimer = 0;
      }

      this.step += dt;
      if (this.step > 0.22) {
        this.step = 0;
        game.addParticle({
          x: this.x + U.rand(-6, 6), y: this.y + this.r * 0.5,
          vx: U.rand(-14, 14), vy: U.rand(-8, 8), life: 0.35,
          size: 4, color: 'rgba(104,98,74,0.25)', drag: 0.9,
        });
      }

      // tấn công công trình gần đó (ban đêm / bị chặn)
      let structureNear = null, sd = 1e9;
      for (const st of game.structures) {
        if (st.dead) continue;
        const d = U.dist(this.x, this.y, st.x, st.y);
        if (d < sd) { sd = d; structureNear = st; }
      }
      if (structureNear && sd < this.r + Math.max(structureNear.w, structureNear.h) / 2 + 12 && this.attackCd <= 0) {
        structureNear.takeDamage(this.damage, game);
        this.attackCd = this.cfg.attackRate;
        this.attackAnim = 0.22;
        game.shake(2, 0.08);
        TT.audio.hit();
      }

      // tấn công mục tiêu
      if (this.attackCd <= 0) {
        if (this.targetKind === 'player' && !p.dead && distT < this.cfg.attackRange + this.r + 6) {
          p.takeDamage(this.damage, game);
          this.attackCd = this.cfg.attackRate;
          this.attackAnim = 0.22;
          game.shake(4, 0.14);
        } else if (this.targetKind === 'soldier' && this.target && !this.target.dead && distT < this.cfg.attackRange + this.r + 6) {
          this.target.takeDamage(this.damage, game);
          this.attackCd = this.cfg.attackRate;
          this.attackAnim = 0.22;
        } else if (this.targetKind === 'structure' && this.target && !this.target.dead && distT < this.cfg.attackRange + this.r + 10) {
          this.target.takeDamage(this.damage, game);
          this.attackCd = this.cfg.attackRate;
          this.attackAnim = 0.22;
        }
      }

      // bắn axit
      if (this.cfg.ranged && distT < this.cfg.range && this.rangedCd <= 0) {
        const target = this.targetKind === 'player' ? p : this.target;
        if (target) {
          this.shootAcid(target, game);
          this.rangedCd = this.cfg.rangedRate * U.rand(0.85, 1.15);
        }
      }

      // boss: húc + bắn chùm
      if (this.type === 'boss' && this.bossRoarCd <= 0 && distT < 600) {
        this.bossRoarCd = 5.5;
        const baseAngle = Math.atan2(p.y - this.y, p.x - this.x);
        for (let i = -2; i <= 2; i++) {
          const a = baseAngle + i * 0.2;
          game.bullets.push(new Bullet(game, {
            x: this.x + Math.cos(a) * 30, y: this.y + Math.sin(a) * 30,
            vx: Math.cos(a) * 300, vy: Math.sin(a) * 300,
            damage: 16, team: 'enemy', life: 2.2, size: 4.5, acid: true,
          }));
        }
        game.shake(9, 0.3);
        TT.audio.bossRoar();
        game.addFloatText(this.x, this.y - 60, 'GẦM GỪ!', '#ff6b3b', 14);
      }
    }

    shootAcid(target, game) {
      const a = Math.atan2(target.y - this.y, target.x - this.x) + U.rand(-0.06, 0.06);
      const speed = 360;
      game.bullets.push(new Bullet(game, {
        x: this.x + Math.cos(a) * this.r, y: this.y + Math.sin(a) * this.r,
        vx: Math.cos(a) * speed, vy: Math.sin(a) * speed,
        damage: this.cfg.projDamage * (1 + 0.08 * (this.night - 1)), team: 'enemy',
        life: 1.6, size: 3.4, acid: true,
      }));
      this.attackAnim = 0.25;
      TT.audio.shoot('enemy');
    }

    pickTarget() {
      const game = this.game;
      const p = game.player;
      const dPlayer = U.dist(this.x, this.y, p.x, p.y);
      const base = game.world.base;
      const dBase = U.dist(this.x, this.y, base.x, base.y);

      // người chơi luôn là ưu tiên nếu ở gần
      if (!p.dead && dPlayer < 330) {
        this.target = p; this.targetKind = 'player'; this.aggro = true; return;
      }

      // ban đêm / đợt sóng: nhắm vào căn cứ
      if (this.waveEnemy || game.nightActive) {
        if (!p.dead && dPlayer < 240) { this.target = p; this.targetKind = 'player'; return; }
        let best = null, bestD = 520;
        for (const st of game.structures) {
          if (st.dead) continue;
          const d = U.dist(this.x, this.y, st.x, st.y);
          if (d < bestD) { bestD = d; best = st; }
        }
        if (!p.dead && dPlayer < 380 && (!best || dPlayer < bestD)) { this.target = p; this.targetKind = 'player'; return; }
        if (best) { this.target = best; this.targetKind = 'structure'; return; }
        if (dBase > 270) { this.target = null; this.targetKind = 'base'; return; }
      }

      // lính gần
      let bestS = null, bd = 480;
      for (const s of game.soldiers) {
        if (s.dead) continue;
        const d = U.dist(this.x, this.y, s.x, s.y);
        if (d < bd) { bd = d; bestS = s; }
      }
      if (bestS && dPlayer > 240) { this.target = bestS; this.targetKind = 'soldier'; return; }

      if (!p.dead && dPlayer < 740) { this.target = p; this.targetKind = 'player'; this.aggro = true; return; }

      // công trình gần để đập
      let best = null, bestD = 220;
      for (const st of game.structures) {
        if (st.dead) continue;
        const d = U.dist(this.x, this.y, st.x, st.y);
        if (d < bestD) { bestD = d; best = st; }
      }
      if (best) { this.target = best; this.targetKind = 'structure'; return; }

      if (dBase < 620) { this.target = null; this.targetKind = 'base'; return; }
      this.target = null; this.targetKind = null;
    }

    move(nx, ny) {
      const dx = nx - this.x, dy = ny - this.y;
      this.x = nx; this.y = ny;
      const hit = this.game.resolveCircle(this, this.r * 0.82);
      if (hit) {
        this.stuckTimer += 0.02;
      }
      this.x = U.clamp(this.x, 80, this.game.world.size - 80);
      this.y = U.clamp(this.y, 80, this.game.world.size - 80);
    }

    draw(ctx) {
      if (this.dead) return;
      const t = performance.now() / 1000;
      const scale = this.type === 'boss' ? 1.65 : this.type === 'brute' ? 1.25 : 1;
      const spawnScale = this.spawnAnim > 0 ? 0.5 + (1 - this.spawnAnim / 0.6) * 0.5 : 1;
      ctx.save();
      ctx.translate(this.x, this.y);
      ctx.scale(scale * spawnScale, scale * spawnScale);

      // bóng
      ctx.fillStyle = 'rgba(2,4,2,0.42)';
      ctx.beginPath();
      ctx.ellipse(3, this.r * 0.65, this.r * 1.1, this.r * 0.45, 0, 0, TAU);
      ctx.fill();

      const swing = Math.sin(this.walkPhase) * 4;
      ctx.save();
      ctx.rotate(this.angle);

      // chân
      ctx.strokeStyle = this.cfg.dark;
      ctx.lineWidth = this.type === 'boss' ? 9 : 5.5;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(-4, -this.r * 0.4); ctx.lineTo(4 + swing, -this.r * 0.7);
      ctx.moveTo(-4, this.r * 0.4); ctx.lineTo(4 - swing, this.r * 0.7);
      ctx.stroke();

      // thân gù
      ctx.fillStyle = this.flash > 0 ? '#fff0d0' : this.cfg.color;
      ctx.beginPath();
      ctx.ellipse(-2, 0, this.r * 0.9, this.r * 0.78, 0, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = this.cfg.dark;
      ctx.lineWidth = 2;
      ctx.stroke();

      // gù lưng
      ctx.fillStyle = this.cfg.dark;
      ctx.beginPath();
      ctx.ellipse(-6, 0, this.r * 0.5, this.r * 0.6, 0.2, 0, TAU);
      ctx.fill();

      if (this.type === 'brute' || this.type === 'boss') {
        ctx.fillStyle = '#78664e';
        for (let i = 0; i < 4; i++) {
          const sy = -this.r * 0.5 + i * this.r * 0.32;
          ctx.beginPath();
          ctx.moveTo(-2, sy);
          ctx.lineTo(-this.r * 0.9, sy - 5);
          ctx.lineTo(-this.r * 0.3, sy + 4);
          ctx.fill();
        }
      }
      if (this.type === 'spitter') {
        ctx.fillStyle = 'rgba(143,200,75,0.65)';
        ctx.beginPath();
        ctx.ellipse(-5, 0, this.r * 0.6, this.r * 0.5, 0, 0, TAU);
        ctx.fill();
      }

      // tay
      ctx.strokeStyle = this.flash > 0 ? '#ffe9c0' : this.cfg.dark;
      ctx.lineWidth = this.type === 'boss' ? 8 : 4;
      const reach = this.attackAnim > 0 ? this.r * 1.5 : this.r * 1.1;
      ctx.beginPath();
      ctx.moveTo(4, -this.r * 0.45);
      ctx.lineTo(reach, -this.r * 0.7 - (this.attackAnim > 0 ? 8 : 0));
      ctx.moveTo(4, this.r * 0.45);
      ctx.lineTo(reach * 0.9, this.r * 0.7 + (this.attackAnim > 0 ? 8 : 0));
      ctx.stroke();
      // móng
      ctx.strokeStyle = '#c4b58f';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(reach, -this.r * 0.7); ctx.lineTo(reach + 5, -this.r * 0.85);
      ctx.moveTo(reach * 0.9, this.r * 0.7); ctx.lineTo(reach * 0.9 + 5, this.r * 0.85);
      ctx.stroke();

      // đầu
      const hx = this.r * 0.55;
      ctx.fillStyle = this.flash > 0 ? '#fff2d5' : '#7f6f54';
      ctx.beginPath();
      ctx.arc(hx, 0, this.r * 0.48, 0, TAU);
      ctx.fill();
      ctx.fillStyle = this.cfg.dark;
      ctx.beginPath();
      ctx.arc(hx - 2, 0, this.r * 0.34, 2.2, 4.2);
      ctx.fill();
      // mắt phát sáng
      ctx.fillStyle = this.cfg.eye;
      ctx.shadowColor = this.cfg.eye;
      ctx.shadowBlur = 8;
      if (this.type === 'boss') {
        for (let i = -1; i <= 1; i++) {
          ctx.beginPath();
          ctx.arc(hx + 2, i * 6, 2.1, 0, TAU);
          ctx.fill();
        }
      } else {
        ctx.beginPath();
        ctx.arc(hx + 1, -3.5, 1.5, 0, TAU);
        ctx.fill();
        ctx.beginPath();
        ctx.arc(hx + 1, 3.5, 1.5, 0, TAU);
        ctx.fill();
      }
      ctx.shadowBlur = 0;

      // miệng
      ctx.strokeStyle = '#3c241c';
      ctx.lineWidth = 1.4;
      ctx.beginPath();
      ctx.arc(hx + 4, 0, this.r * 0.28, 0.4, Math.PI - 0.4);
      ctx.stroke();

      // vết thương nhấp nháy khi trúng đòn
      if (this.flash > 0) {
        ctx.globalAlpha = this.flash / 0.09;
        ctx.fillStyle = '#ffe4b0';
        ctx.beginPath();
        ctx.arc(0, 0, this.r * 0.65, 0, TAU);
        ctx.fill();
        ctx.globalAlpha = 1;
      }
      ctx.restore();

      // thanh máu
      if (this.hpShow > 0 || this.type === 'boss') {
        const w = this.type === 'boss' ? 90 : this.type === 'brute' ? 40 : 28;
        const y = -this.r * scale - (this.type === 'boss' ? 26 : 14);
        ctx.fillStyle = 'rgba(0,0,0,0.55)';
        ctx.fillRect(-w / 2 - 1, y - 1, w + 2, 5);
        ctx.fillStyle = this.type === 'boss' ? '#b33d28' : '#a94535';
        ctx.fillRect(-w / 2, y, w, 3);
        ctx.fillStyle = this.type === 'boss' ? '#ff8b5c' : '#e47b58';
        ctx.fillRect(-w / 2, y, w * U.clamp(this.hp / this.maxHp, 0, 1), 3);
        if (this.type === 'boss') {
          ctx.font = '700 7px ui-monospace, monospace';
          ctx.textAlign = 'center';
          ctx.fillStyle = '#ffbf91';
          ctx.fillText('QUÁI VẬT CHÚA', 0, y - 6);
          ctx.textAlign = 'left';
        }
      }

      // chỉ báo máu thấp
      ctx.restore();
    }
  }

  /* ============================================================
     LÍNH AI
     ============================================================ */
  class Soldier {
    constructor(game, x, y, name, index) {
      this.game = game;
      this.x = x; this.y = y;
      this.homeX = x; this.homeY = y;
      this.r = 13;
      this.name = name || 'LÍNH';
      this.index = index || 0;
      this.maxHp = 120 + game.baseLevel * 18;
      this.hp = this.maxHp;
      this.speed = 205;
      this.angle = U.rand(0, TAU);
      this.aimAngle = this.angle;
      this.moveAngle = 0;
      this.walkPhase = 0;
      this.moving = false;
      this.target = null;
      this.fireCd = U.rand(0, 0.8);
      this.dead = false;
      this.flash = 0;
      this.muzzle = 0;
      this.think = 0;
      this.damage = 13 + game.baseLevel * 1.5;
      this.followOffset = { x: Math.cos(index * 2.1) * 90, y: 60 + Math.sin(index * 2.1) * 70 };
      this.step = 0;
    }

    takeDamage(amount, game) {
      if (this.dead) return;
      this.hp -= amount;
      this.flash = 0.1;
      game.addFloatText(this.x, this.y - 24, `-${Math.round(amount)}`, '#ff9a80', 10);
      this.hpShow = 2;
      for (let i = 0; i < 5; i++) {
        game.addParticle({ x: this.x, y: this.y, vx: U.rand(-80, 80), vy: U.rand(-80, 80), life: 0.3, size: 2, color: '#8f2b21', type: 'spark' });
      }
      if (this.hp <= 0) {
        this.hp = 0;
        this.dead = true;
        game.onSoldierDown(this);
      }
    }

    update(dt) {
      if (this.dead) return;
      this.flash = Math.max(0, this.flash - dt);
      this.fireCd = Math.max(0, this.fireCd - dt);
      this.muzzle = Math.max(0, this.muzzle - dt);
      this.hpShow = Math.max(0, (this.hpShow || 0) - dt);
      this.think -= dt;
      const game = this.game;
      const p = game.player;

      if (this.think <= 0) {
        this.think = 0.35;
        let best = null, bd = 560;
        for (const e of game.enemies) {
          if (e.dead) continue;
          const d = U.dist(this.x, this.y, e.x, e.y);
          if (d < bd) { bd = d; best = e; }
        }
        this.target = best;
      }

      let tx, ty;
      const nearPlayer = U.dist(this.x, this.y, p.x, p.y) < 1000 && !p.dead;
      if (this.target) {
        const d = U.dist(this.x, this.y, this.target.x, this.target.y);
        const desired = 210;
        if (d > desired) { tx = this.target.x; ty = this.target.y; }
        else if (d < 130) {
          tx = this.x - (this.target.x - this.x); ty = this.y - (this.target.y - this.y);
        } else { tx = this.x; ty = this.y; }
        this.aimAngle += U.angleDiff(this.aimAngle, Math.atan2(this.target.y - this.y, this.target.x - this.x)) * Math.min(1, dt * 10);
        if (d < 470 && this.fireCd <= 0) this.fire();
      } else {
        if (nearPlayer) {
          tx = p.x + this.followOffset.x;
          ty = p.y + this.followOffset.y;
        } else {
          const a = performance.now() / 5000 + this.index * 2;
          tx = game.world.base.x + Math.cos(a) * 180;
          ty = game.world.base.y + Math.sin(a) * 150;
        }
        const d = U.dist(this.x, this.y, tx, ty);
        if (d < 36) { tx = this.x; ty = this.y; }
        this.aimAngle += U.angleDiff(this.aimAngle, Math.atan2(ty - this.y, tx - this.x)) * Math.min(1, dt * 4);
      }

      const d = U.dist(this.x, this.y, tx, ty);
      if (d > 10) {
        const a = Math.atan2(ty - this.y, tx - this.x);
        this.moveAngle = a;
        const len = Math.min(d, this.speed * dt);
        this.x += Math.cos(a) * len;
        this.y += Math.sin(a) * len;
        this.game.resolveCircle(this, this.r);
        this.walkPhase += dt * 9;
        this.moving = true;
        this.step += dt;
        if (this.step > 0.3) {
          this.step = 0;
          game.addParticle({ x: this.x, y: this.y + 8, vx: U.rand(-8, 8), vy: U.rand(-5, 5), life: 0.3, size: 3, color: 'rgba(110,103,76,0.25)' });
        }
      } else {
        this.moving = false;
      }
    }

    fire() {
      const game = this.game;
      const spread = 0.06;
      const a = this.aimAngle + U.rand(-spread, spread);
      const range = 470;
      game.bullets.push(new Bullet(game, {
        x: this.x + Math.cos(a) * 16, y: this.y + Math.sin(a) * 16,
        vx: Math.cos(a) * 1150, vy: Math.sin(a) * 1150,
        damage: this.damage, team: 'soldier', life: range / 1150, size: 2, color: '#d9e7a9',
      }));
      this.fireCd = 0.38;
      this.muzzle = 0.06;
      TT.audio.shoot('soldier');
      game.addParticle({ x: this.x + Math.cos(a) * 20, y: this.y + Math.sin(a) * 20, vx: U.rand(-20, 20), vy: U.rand(-20, 20), life: 0.12, size: 4, color: '#ffd58a', glow: true });
    }

    draw(ctx) {
      if (this.dead) return;
      ctx.save();
      ctx.translate(this.x, this.y);
      // bóng
      ctx.fillStyle = 'rgba(2,4,2,0.4)';
      ctx.beginPath(); ctx.ellipse(3, 10, 15, 7, 0, 0, TAU); ctx.fill();
      // chân
      const swing = this.moving ? Math.sin(this.walkPhase) * 6 : 0;
      ctx.save(); ctx.rotate(this.moveAngle);
      ctx.strokeStyle = '#39402f'; ctx.lineWidth = 6; ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(-2, -5); ctx.lineTo(3 + swing, -8);
      ctx.moveTo(-2, 5); ctx.lineTo(3 - swing, 8);
      ctx.stroke();
      ctx.restore();
      // thân
      ctx.save(); ctx.rotate(this.aimAngle);
      if (this.flash > 0) ctx.globalAlpha = 0.7;
      ctx.fillStyle = '#6f6241';
      ctx.beginPath(); ctx.ellipse(0, 0, 10, 12, 0, 0, TAU); ctx.fill();
      ctx.strokeStyle = '#3c3524'; ctx.lineWidth = 1.4; ctx.stroke();
      ctx.fillStyle = '#83754d';
      ctx.fillRect(-8, -8, 5, 16);
      // đầu
      ctx.fillStyle = this.flash > 0 ? '#ffe5cf' : '#bd8c60';
      ctx.beginPath(); ctx.arc(3, 0, 6.4, 0, TAU); ctx.fill();
      ctx.fillStyle = '#4b4a2c';
      ctx.beginPath(); ctx.arc(2, 0, 6.8, 1.5, 4.8); ctx.fill();
      // súng
      ctx.fillStyle = '#2f332a';
      ctx.fillRect(9, -1.8, 27, 3.8);
      ctx.fillStyle = '#585c48';
      ctx.fillRect(11, -2.2, 14, 1.5);
      ctx.fillStyle = '#6e5534';
      ctx.fillRect(8, 0, 6, 4);
      if (this.muzzle > 0) {
        ctx.globalCompositeOperation = 'lighter';
        ctx.fillStyle = 'rgba(255,208,120,0.8)';
        ctx.beginPath(); ctx.arc(37, 0, 8, 0, TAU); ctx.fill();
        ctx.globalCompositeOperation = 'source-over';
      }
      ctx.restore();
      // tên
      if (this.hpShow > 0 || this.hp < this.maxHp) {
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
        ctx.fillRect(-16, -30, 32, 4);
        ctx.fillStyle = '#9ed47f';
        ctx.fillRect(-16, -30, 32 * U.clamp(this.hp / this.maxHp, 0, 1), 4);
      }
      ctx.font = '700 6px ui-monospace, monospace';
      ctx.textAlign = 'center';
      ctx.fillStyle = 'rgba(190,205,160,0.8)';
      ctx.fillText(this.name, 0, -34);
      ctx.textAlign = 'left';
      ctx.restore();
    }
  }

  /* ============================================================
     CÔNG TRÌNH
     ============================================================ */
  class Structure {
    constructor(game, kind, x, y, angle = 0, level = 1) {
      this.game = game;
      this.kind = kind;
      this.def = TT.BUILD[kind];
      this.x = x; this.y = y;
      this.baseW = this.def.w;
      this.baseH = this.def.h;
      this.angle = angle;
      this.level = level;
      this.maxHp = Math.round(this.def.hp * (1 + 0.4 * (level - 1)));
      this.hp = this.maxHp;
      this.dead = false;
      this.fireCd = U.rand(0, 0.4);
      this.aim = U.rand(0, TAU);
      this.target = null;
      this.flash = 0;
      this.muzzle = 0;
      this.pulse = 0;
      this.applyRotation();
    }

    applyRotation() {
      const swap = this.angle > 0.1 && this.angle < Math.PI - 0.1;
      this.w = swap ? this.baseH : this.baseW;
      this.h = swap ? this.baseW : this.baseH;
    }

    takeDamage(amount, game) {
      if (this.dead) return;
      this.hp -= amount;
      this.flash = 0.1;
      game.addFloatText(this.x + U.rand(-8, 8), this.y - this.h / 2 - 8, `-${Math.round(amount)}`, '#e8a26f', 9);
      for (let i = 0; i < 4; i++) {
        game.addParticle({
          x: this.x + U.rand(-this.w / 2, this.w / 2), y: this.y + U.rand(-this.h / 2, this.h / 2),
          vx: U.rand(-100, 100), vy: U.rand(-100, 100), life: 0.35,
          size: U.rand(1.5, 3.5), color: '#806b45', type: 'spark',
        });
      }
      TT.audio.hit();
      if (this.hp <= 0) {
        this.dead = true;
        game.onStructureDestroyed(this);
      }
    }

    update(dt) {
      if (this.dead) return;
      this.flash = Math.max(0, this.flash - dt);
      this.muzzle = Math.max(0, this.muzzle - dt);
      this.pulse += dt;
      if (this.kind === 'turret') this.updateTurret(dt);
      if (this.kind === 'medic') this.updateMedic(dt);
    }

    updateTurret(dt) {
      const game = this.game;
      this.fireCd = Math.max(0, this.fireCd - dt);
      if (this.target && (this.target.dead || U.dist(this.x, this.y, this.target.x, this.target.y) > 540)) this.target = null;
      if (!this.target) {
        let best = null, bd = 480 + this.level * 30;
        for (const e of game.enemies) {
          if (e.dead) continue;
          const d = U.dist(this.x, this.y, e.x, e.y);
          if (d < bd) { bd = d; best = e; }
        }
        this.target = best;
      }
      if (this.target) {
        const a = Math.atan2(this.target.y - this.y, this.target.x - this.x);
        this.aim += U.angleDiff(this.aim, a) * Math.min(1, dt * 8);
        if (Math.abs(U.angleDiff(this.aim, a)) < 0.2 && this.fireCd <= 0) {
          const spread = 0.025;
          const ba = this.aim + U.rand(-spread, spread);
          const dmg = (12 + this.level * 4) * (1 + 0.12 * (game.baseLevel - 1));
          game.bullets.push(new Bullet(game, {
            x: this.x + Math.cos(this.aim) * 24, y: this.y + Math.sin(this.aim) * 24,
            vx: Math.cos(ba) * 1200, vy: Math.sin(ba) * 1200,
            damage: dmg, team: 'turret', life: 0.65, size: 2.4, color: '#b7f2e2',
          }));
          this.fireCd = 0.4 / (1 + 0.18 * (this.level - 1));
          this.muzzle = 0.07;
          TT.audio.shoot('turret');
          game.addParticle({
            x: this.x + Math.cos(this.aim) * 26, y: this.y + Math.sin(this.aim) * 26,
            vx: U.rand(-20, 20), vy: U.rand(-20, 20), life: 0.1, size: 4,
            color: '#c8fff2', glow: true,
          });
        }
      }
    }

    updateMedic(dt) {
      const game = this.game;
      const range = 150 + this.level * 15;
      for (const s of game.soldiers) {
        if (s.dead) continue;
        if (U.dist(this.x, this.y, s.x, s.y) < range && s.hp < s.maxHp) s.hp = Math.min(s.maxHp, s.hp + 3 * dt);
      }
      const p = game.player;
      if (!p.dead && U.dist(this.x, this.y, p.x, p.y) < range && p.hp < p.maxHp) {
        p.hp = Math.min(p.maxHp, p.hp + 3.2 * dt);
        if (Math.random() < dt * 3) {
          game.addParticle({
            x: p.x + U.rand(-12, 12), y: p.y + U.rand(-10, 10),
            vx: 0, vy: -16, life: 0.7, size: 2.2, color: '#9fe08c', glow: true,
          });
        }
      }
    }

    draw(ctx) {
      if (this.dead) return;
      const t = performance.now() / 1000;
      ctx.save();
      ctx.translate(this.x, this.y);
      // bóng
      ctx.fillStyle = 'rgba(2,4,2,0.38)';
      ctx.fillRect(-this.w / 2 + 4, -this.h / 2 + 7, this.w, this.h);

      if (this.kind === 'wall' || this.kind === 'barricade') {
        ctx.rotate(this.angle);
        const w = this.baseW, h = this.baseH;
        if (this.kind === 'wall') {
          ctx.fillStyle = this.flash > 0 ? '#b7a47c' : '#655636';
          ctx.fillRect(-w / 2, -h / 2, w, h);
          ctx.fillStyle = 'rgba(157,138,92,0.6)';
          ctx.fillRect(-w / 2, -h / 2, w, 4);
          ctx.fillStyle = 'rgba(38,32,19,0.55)';
          for (let i = 0; i < 4; i++) {
            ctx.fillRect(-w / 2 + 6 + i * (w - 12) / 3.4, -h / 2 + 4, 1.5, h - 8);
          }
          ctx.strokeStyle = '#37301e';
          ctx.lineWidth = 2;
          ctx.strokeRect(-w / 2, -h / 2, w, h);
          ctx.fillStyle = '#8e7c4f';
          for (let i = 0; i < 4; i++) {
            ctx.beginPath();
            ctx.arc(-w / 2 + 12 + i * (w - 24) / 3, 0, 1.7, 0, TAU);
            ctx.fill();
          }
          if (this.level > 1) {
            ctx.strokeStyle = 'rgba(218,183,104,0.8)';
            ctx.lineWidth = 1.5;
            ctx.strokeRect(-w / 2 + 3, -h / 2 + 3, w - 6, h - 6);
          }
        } else {
          ctx.fillStyle = this.flash > 0 ? '#b7a47c' : '#4f432d';
          ctx.fillRect(-w / 2, -h / 2, w, h);
          ctx.strokeStyle = '#31291b';
          ctx.lineWidth = 2;
          for (let i = -w / 2 + 8; i < w / 2; i += 12) {
            ctx.beginPath();
            ctx.moveTo(i, h / 2);
            ctx.lineTo(i + 6, -h / 2 - 5);
            ctx.stroke();
          }
          ctx.fillStyle = '#736443';
          ctx.fillRect(-w / 2, -h / 2, w, 4);
        }
      } else if (this.kind === 'turret') {
        // đế
        ctx.fillStyle = this.flash > 0 ? '#cbbfa3' : '#3c4437';
        ctx.beginPath();
        ctx.arc(0, 0, 20, 0, TAU);
        ctx.fill();
        ctx.strokeStyle = '#252c22';
        ctx.lineWidth = 2;
        ctx.stroke();
        ctx.fillStyle = '#2b3228';
        ctx.beginPath();
        ctx.arc(0, 0, 14, 0, TAU);
        ctx.fill();
        // thân xoay
        ctx.save();
        ctx.rotate(this.aim);
        ctx.fillStyle = '#596552';
        ctx.fillRect(-4, -8, 18, 16);
        ctx.fillStyle = '#78856b';
        ctx.fillRect(0, -6, 14, 3);
        ctx.fillRect(0, 3, 14, 3);
        ctx.fillStyle = '#2d3428';
        ctx.fillRect(20, -5, 9, 2.5);
        ctx.fillRect(20, 2.5, 9, 2.5);
        if (this.muzzle > 0) {
          ctx.globalCompositeOperation = 'lighter';
          ctx.fillStyle = 'rgba(200,255,240,0.75)';
          ctx.beginPath(); ctx.arc(30, 0, 8, 0, TAU); ctx.fill();
          ctx.globalCompositeOperation = 'source-over';
        }
        ctx.restore();
        // cấp
        for (let i = 0; i < this.level; i++) {
          ctx.fillStyle = '#d6b56f';
          ctx.fillRect(-10 + i * 7, -25, 4, 2.5);
        }
      } else if (this.kind === 'medic') {
        const pulse = (Math.sin(t * 2.4) + 1) / 2;
        ctx.strokeStyle = `rgba(138,203,114,${0.12 + pulse * 0.1})`;
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(0, 0, 42 + pulse * 8, 0, TAU);
        ctx.stroke();
        ctx.fillStyle = this.flash > 0 ? '#e4f0d8' : '#46513d';
        ctx.beginPath();
        ctx.arc(0, 0, 20, 0, TAU);
        ctx.fill();
        ctx.strokeStyle = '#293225';
        ctx.lineWidth = 2;
        ctx.stroke();
        ctx.fillStyle = '#dbe9ce';
        ctx.fillRect(-4, -11, 8, 22);
        ctx.fillRect(-11, -4, 22, 8);
        ctx.fillStyle = '#8fbf7a';
        ctx.beginPath();
        ctx.arc(0, 0, 3, 0, TAU);
        ctx.fill();
      }

      // thanh máu
      if (this.hp < this.maxHp) {
        const bw = Math.max(34, this.w);
        ctx.fillStyle = 'rgba(0,0,0,0.55)';
        ctx.fillRect(-bw / 2 - 1, -this.h / 2 - 11, bw + 2, 5);
        ctx.fillStyle = '#b06a3f';
        ctx.fillRect(-bw / 2, -this.h / 2 - 10, bw, 3);
        ctx.fillStyle = '#e3be75';
        ctx.fillRect(-bw / 2, -this.h / 2 - 10, bw * U.clamp(this.hp / this.maxHp, 0, 1), 3);
      }
      ctx.restore();
    }
  }

  TT.Particle = Particle;
  TT.FloatText = FloatText;
  TT.Bullet = Bullet;
  TT.Player = Player;
  TT.Enemy = Enemy;
  TT.Soldier = Soldier;
  TT.Structure = Structure;
})();

/* ============================================================
   ui.js — HUD, bảng điều khiển, sổ tay, điều hướng giao diện
   ============================================================ */
(function () {
  'use strict';
  const U = TT.U;
  const $ = (id) => document.getElementById(id);

  const RES_LABEL = { scrap: 'phế liệu', wood: 'gỗ', food: 'lương thực', parts: 'linh kiện', medkit: 'bộ y tế' };
  const AMMO_LABEL = { ammo9: 'đạn 9mm', shell: 'đạn ghém', ammo556: 'đạn 5.56' };

  class UI {
    constructor(game) {
      this.game = game;
      this.el = {
        menu: $('menu'), hud: $('hud'), mobile: $('mobileControls'), panel: $('panel'),
        pause: $('pauseScreen'), death: $('deathScreen'), guide: $('guideScreen'),
        buildBar: $('buildBar'), buildItems: $('buildItems'),
        hpFill: $('hpFill'), hpText: $('hpText'), stamFill: $('stamFill'), xpFill: $('xpFill'),
        xpText: $('xpText'), levelChip: $('levelChip'), hpStatus: $('hpStatus'),
        clock: $('clockText'), day: $('dayText'), phase: $('phaseText'), threat: $('threatText'),
        timeIcon: $('timeIcon'), cycleFill: $('cycleFill'),
        wavePanel: $('wavePanel'), waveNumber: $('waveNumber'), waveFill: $('waveFill'), waveInfo: $('waveInfo'),
        resScrap: $('resScrap'), resWood: $('resWood'), resFood: $('resFood'), resParts: $('resParts'),
        minimap: $('minimap'), mapCoords: $('mapCoords'), questList: $('questList'), questCount: $('questCount'),
        weaponDock: $('weaponDock'), prompt: $('interactPrompt'), promptText: $('interactText'),
        toasts: $('toasts'), banner: $('banner'), crosshair: $('crosshair'), damageFlash: $('damageFlash'),
        lowHealth: $('lowHealth'), statusTags: $('statusTags'),
        panelKicker: $('panelKicker'), panelTitle: $('panelTitle'), panelRes: $('panelRes'),
        panelTabs: $('panelTabs'), panelBody: $('panelBody'), panelFoot: $('panelFoot'),
        pauseStats: $('pauseStats'), deathStats: $('deathStats'), deathEpitaph: $('deathEpitaph'),
        dashCd: $('dashCd'), keyHints: $('keyHints'), guide: $('guideScreen'),
      };
      this.weaponEls = [];
      this.questSignature = '';
      this.lastRes = {};
      this.lastPrompt = '';
      this.cache = {};
      this.bannerTimer = null;
      this.minimapTimer = 0;
      this.flashTimer = null;
      this.bind();
      this.buildWeaponDock();
    }

    bind() {
      const g = this.game;
      // menu
      $('btnStart').addEventListener('click', () => { TT.audio.init(); g.startGame(); });
      $('btnGuide').addEventListener('click', () => g.openGuide());
      $('guideClose').addEventListener('click', () => g.closeGuide());
      $('guideDone').addEventListener('click', () => g.closeGuide());
      $('pauseBtn').addEventListener('click', () => g.pause());
      $('btnResume').addEventListener('click', () => g.resume());
      $('btnPauseGuide').addEventListener('click', () => g.openGuide());
      $('btnQuit').addEventListener('click', () => g.quitToMenu());
      $('btnRetry').addEventListener('click', () => g.startGame());
      $('btnDeathMenu').addEventListener('click', () => g.quitToMenu());
      $('panelClose').addEventListener('click', () => g.closePanel());
      $('buildClose').addEventListener('click', () => g.toggleBuild(false));

      // HUD abilities
      $('abilityDash').addEventListener('click', () => g.tryDash());
      $('abilityReload').addEventListener('click', () => g.player && g.player.startReload());
      $('abilityBuild').addEventListener('click', () => g.toggleBuild());
      $('abilityHub').addEventListener('click', () => g.openHub());
      const healBtn = $('abilityHeal');
      if (healBtn) healBtn.addEventListener('click', () => g.useMedkit());

      // build bar
      this.el.buildItems.addEventListener('click', (e) => {
        const item = e.target.closest('[data-build]');
        if (!item) return;
        g.selectBuild(item.dataset.build);
      });
      // panel actions
      this.el.panelBody.addEventListener('click', (e) => {
        const tab = e.target.closest('[data-tab]');
        if (tab) { g.openPanel('hub', tab.dataset.tab); return; }
        const btn = e.target.closest('[data-action]');
        if (!btn) return;
        const action = btn.dataset.action;
        if (action === 'upgrade-weapon') g.upgradeWeapon(btn.dataset.id);
        else if (action === 'upgrade-base') g.upgradeBase();
        else if (action === 'recruit') g.recruitSoldier();
        else if (action === 'buy') g.buySupply(btn.dataset.id);
        else if (action === 'build') { g.closePanel(); g.toggleBuild(true); }
        else if (action === 'close') g.closePanel();
        if (document.activeElement && document.activeElement.blur) document.activeElement.blur();
      });
      this.el.panelTabs.addEventListener('click', (e) => {
        const tab = e.target.closest('[data-tab]');
        if (tab) g.openPanel('hub', tab.dataset.tab);
      });

      // weapon dock (event delegation)
      this.el.weaponDock.addEventListener('click', (e) => {
        const slot = e.target.closest('[data-slot]');
        if (slot && g.player) g.player.switchWeapon(Number(slot.dataset.slot));
      });
    }

    /* ---------------- weapon dock ---------------- */
    buildWeaponDock() {
      if (!this.game.player) return;
      this.el.weaponDock.innerHTML = '';
      this.weaponEls = [];
      this.game.player.weapons.forEach((w, i) => {
        const b = document.createElement('button');
        b.className = 'weapon-slot';
        b.dataset.slot = i;
        b.innerHTML = `<span class="wkey">${w.slot}</span><span class="wname">${w.name}</span><span class="wammo"></span><span class="wlvl"></span>`;
        this.el.weaponDock.appendChild(b);
        this.weaponEls.push(b);
      });
      this.refreshWeapons();
    }

    refreshWeapons() {
      const p = this.game.player;
      if (!p) return;
      p.weapons.forEach((w, i) => {
        const el = this.weaponEls[i];
        if (!el) return;
        el.classList.toggle('active', p.current === i);
        el.classList.toggle('empty', !w.owned);
        el.querySelector('.wname').textContent = w.owned ? w.name : '???';
        const ammoEl = el.querySelector('.wammo');
        if (!w.owned) ammoEl.textContent = 'CHƯA MỞ KHÓA';
        else if (w.type === 'melee') ammoEl.textContent = 'CẬN CHIẾN';
        else ammoEl.textContent = `${w.mag} / ${this.game.ammo[w.ammoType]}`;
        el.querySelector('.wlvl').textContent = w.owned ? (w.level > 1 ? 'L' + w.level : '') : '🔒';
      });
    }

    /* ---------------- HUD ---------------- */
    showHud() {
      this.el.hud.classList.remove('hidden');
      if (this.game.isTouch) this.el.mobile.classList.remove('hidden');
      this.el.crosshair.classList.toggle('visible', !this.game.isTouch);
    }
    hideHud() {
      this.el.hud.classList.add('hidden');
      this.el.mobile.classList.add('hidden');
      this.el.crosshair.classList.remove('visible');
    }

    update(dt, force = false) {
      const g = this.game;
      const p = g.player;
      if (!p) return;
      this.cache.t = (this.cache.t || 0) + dt;
      this.minimapTimer -= dt;
      if (this.minimapTimer <= 0) {
        this.minimapTimer = 0.18;
        g.world.drawMinimap(this.el.minimap.getContext('2d'), g);
        this.el.mapCoords.textContent = `${Math.round(p.x)} : ${Math.round(p.y)}`;
      }
      if (!force && this.cache.t < 0.1) return;
      this.cache.t = 0;

      const hpPct = U.clamp(p.hp / p.maxHp, 0, 1) * 100;
      this.el.hpFill.style.width = hpPct + '%';
      this.el.hpText.textContent = `${Math.ceil(p.hp)} / ${p.maxHp}`;
      this.el.stamFill.style.width = U.clamp(p.stamina / p.maxStamina, 0, 1) * 100 + '%';
      this.el.xpFill.style.width = U.clamp(p.xp / p.xpNext, 0, 1) * 100 + '%';
      this.el.xpText.textContent = `${Math.floor(p.xp)} / ${p.xpNext} XP`;
      this.el.levelChip.textContent = p.level;
      const status = p.hp / p.maxHp;
      this.el.hpStatus.textContent = status > 0.65 ? 'ỔN ĐỊNH' : status > 0.3 ? 'BỊ THƯƠNG' : 'NGUY KỊCH';
      this.el.hpStatus.className = status > 0.65 ? '' : status > 0.3 ? 'wounded' : 'critical';
      this.el.lowHealth.style.opacity = status < 0.3 ? '1' : '0';

      // đồng hồ / chu kỳ
      const hour = g.hour();
      const hh = Math.floor(hour);
      const mm = Math.floor((hour - hh) * 60);
      this.el.clock.textContent = `${U.pad2(hh)}:${U.pad2(Math.floor(mm / 1) * 1)}`;
      this.el.day.textContent = `NGÀY ${g.day}`;
      const phase = g.phaseInfo();
      this.el.phase.textContent = phase.name;
      this.el.threat.textContent = phase.threat;
      this.el.threat.style.color = phase.color;
      this.el.timeIcon.textContent = phase.icon;
      this.el.timeIcon.style.color = phase.color;
      this.el.timeIcon.style.borderColor = phase.color + '55';
      this.el.cycleFill.style.width = (hour / 24) * 100 + '%';

      // đợt sóng
      if (g.nightActive) {
        this.el.wavePanel.classList.remove('hidden');
        this.el.waveNumber.textContent = String(Math.max(1, g.waveNumber));
        const alive = g.enemies.filter(e => e.waveEnemy && !e.dead).length;
        const queue = Math.max(0, g.waveTotal - g.waveSpawned);
        const total = Math.max(1, g.waveTotal);
        this.el.waveFill.style.width = U.clamp(alive / total, 0, 1) * 100 + '%';
        if (!g.waveActive) this.el.waveInfo.textContent = `ĐỢT TIẾP THEO: ${Math.ceil(g.waveTimer)} GIÂY · HÃY CỐ THỦ`;
        else if (queue > 0) this.el.waveInfo.textContent = `ĐANG TRIỂN KHAI · CÒN ${alive + queue} DỊ BIẾN`;
        else this.el.waveInfo.textContent = `CÒN ${alive} DỊ BIẾN · ĐẨY LÙI CHÚNG`;
      } else {
        this.el.wavePanel.classList.add('hidden');
      }

      // tài nguyên
      const res = g.resources;
      this.setRes('resScrap', res.scrap);
      this.setRes('resWood', res.wood);
      this.setRes('resFood', res.food);
      this.setRes('resParts', res.parts);

      // nhiệm vụ
      this.updateQuests();

      // vũ khí
      this.refreshWeapons();

      // hồi máu
      const heal = $('abilityHeal');
      if (heal) {
        const small = heal.querySelector('small');
        if (small) small.textContent = `MÁU x${res.medkit}`;
      }

      // hồi chiêu lướt
      const dashPct = g.player.dashCd > 0 ? (1 - g.player.dashCd / 2.2) * 100 : 100;
      this.el.dashCd.style.width = U.clamp(dashPct, 0, 100) + '%';

      // trạng thái
      const tags = [];
      if (g.nightActive) tags.push('BAN ĐÊM · NGUY HIỂM');
      if (p.reloadTimer > 0) tags.push('ĐANG NẠP ĐẠN');
      if (p.dashCd > 0 && p.dashCd < 0.3) tags.push('LƯỚT HỒI');
      this.el.statusTags.innerHTML = tags.map(t => `<span class="status-tag">${t}</span>`).join('');

      // thông báo tương tác
      const target = g.getInteractTarget();
      if (target && !g.buildMode && g.state === 'playing') {
        if (target.label !== this.lastPrompt) {
          this.el.promptText.textContent = target.label;
          this.lastPrompt = target.label;
        }
        this.el.prompt.classList.remove('hidden');
      } else {
        this.el.prompt.classList.add('hidden');
        this.lastPrompt = '';
      }
      this.updateCrosshair();
    }

    updateCrosshair() {
      const g = this.game;
      if (g.isTouch || g.state !== 'playing') {
        this.el.crosshair.classList.remove('visible');
        return;
      }
      this.el.crosshair.classList.add('visible');
      this.el.crosshair.style.left = g.input.mouse.x + 'px';
      this.el.crosshair.style.top = g.input.mouse.y + 'px';
      const w = g.player.weapon;
      const spread = w.type === 'gun' ? 5 + w.spread * 80 : 2;
      this.el.crosshair.style.transform = `translate(-50%, -50%) scale(${1 + spread / 30})`;
    }

    setRes(id, value) {
      const el = this.el[id];
      if (!el) return;
      const key = id;
      if (this.lastRes[key] !== value) {
        el.textContent = U.fmt(value);
        if (this.lastRes[key] !== undefined) {
          el.parentElement.classList.remove('flash');
          void el.parentElement.offsetWidth;
          el.parentElement.classList.add('flash');
        }
        this.lastRes[key] = value;
      }
    }

    updateQuests() {
      const qs = this.game.activeQuests;
      const sig = qs.map(q => `${q.title}:${q.progress}/${q.target}`).join('|');
      this.el.questCount.textContent = `${qs.filter(q => q.progress >= q.target).length}/${qs.length}`;
      if (sig === this.questSignature) return;
      this.questSignature = sig;
      this.el.questList.innerHTML = qs.map(q => {
        const done = q.progress >= q.target;
        const pct = U.clamp(q.progress / q.target, 0, 1) * 100;
        return `<div class="quest-item ${done ? 'done' : ''}">
          <div class="quest-title-row"><span>${q.title}</span><b>${Math.min(q.target, Math.floor(q.progress))}/${q.target}</b></div>
          <div class="quest-progress"><i style="width:${pct}%"></i></div>
        </div>`;
      }).join('');
    }

    toast(text, type = 'info', icon = '◆') {
      const el = document.createElement('div');
      el.className = 'toast ' + (type === 'good' ? 'good' : type === 'bad' ? 'bad' : '');
      el.innerHTML = `<span class="tico">${icon}</span><span>${text}</span>`;
      this.el.toasts.prepend(el);
      while (this.el.toasts.children.length > 4) this.el.toasts.lastChild.remove();
      setTimeout(() => {
        el.classList.add('out');
        setTimeout(() => el.remove(), 360);
      }, 3200);
    }

    banner(kicker, title, sub, duration = 3.2) {
      const b = this.el.banner;
      b.innerHTML = `<small>${kicker}</small><strong>${title}</strong><em>${sub || ''}</em>`;
      b.classList.remove('hidden');
      b.style.animation = 'none';
      void b.offsetWidth;
      b.style.animation = 'bannerIn 0.5s ease-out';
      clearTimeout(this.bannerTimer);
      this.bannerTimer = setTimeout(() => b.classList.add('hidden'), duration * 1000);
    }

    flashDamage() {
      this.el.damageFlash.style.opacity = '1';
      clearTimeout(this.flashTimer);
      this.flashTimer = setTimeout(() => { this.el.damageFlash.style.opacity = '0'; }, 130);
    }

    /* ---------------- BUILD BAR ---------------- */
    refreshBuildBar() {
      const g = this.game;
      this.el.buildItems.innerHTML = Object.values(TT.BUILD).map(def => {
        const active = g.buildType === def.id;
        const afford = g.canAfford(def.cost);
        const costs = Object.entries(def.cost).map(([k, v]) => {
          const lack = g.resources[k] < v;
          return `<span class="${lack ? 'lack' : ''}">${def.id ? '' : ''}${v} ${RES_LABEL[k]}</span>`;
        }).join('');
        return `<button class="build-item ${active ? 'active' : ''} ${afford ? '' : 'disabled'}" data-build="${def.id}">
          <div class="bi-top"><strong>${def.name}</strong><span class="bi-key">${def.key}</span></div>
          <small>${def.desc}</small>
          <div class="build-cost">${costs}</div>
        </button>`;
      }).join('');
    }

    /* ---------------- PANEL ---------------- */
    openPanel(tabId = 'command') {
      this.el.panel.classList.remove('hidden');
      this.renderPanel(tabId);
    }
    closePanel() {
      this.el.panel.classList.add('hidden');
    }

    renderPanel(tabId) {
      const g = this.game;
      this.el.panelKicker.textContent = 'TRUNG TÂM CHỈ HUY · TRẠM 07';
      this.el.panelTitle.textContent = 'CĂN CỨ TRẠM 07';
      this.el.panelFoot.textContent = `Trạm 07 · Ngày ${g.day} · ${g.nightActive ? 'Ban đêm' : 'Ban ngày'} · Cấp căn cứ ${g.baseLevel}`;
      const tabs = [
        ['command', 'CHỈ HUY'], ['weapons', 'VŨ KHÍ'], ['recruit', 'CHIÊU MỘ'],
        ['supply', 'TIẾP TẾ'], ['quests', 'NHIỆM VỤ'],
      ];
      this.el.panelTabs.innerHTML = tabs.map(([id, name]) =>
        `<button class="panel-tab ${id === tabId ? 'active' : ''}" data-tab="${id}">${name}</button>`).join('');
      const r = g.resources;
      this.el.panelRes.innerHTML = `
        <div><span>PHẾ LIỆU</span><b>${U.fmt(r.scrap)}</b></div>
        <div><span>GỖ</span><b>${U.fmt(r.wood)}</b></div>
        <div><span>LƯƠNG</span><b>${U.fmt(r.food)}</b></div>
        <div><span>LINH KIỆN</span><b>${U.fmt(r.parts)}</b></div>`;

      if (tabId === 'weapons') this.el.panelBody.innerHTML = this.weaponsTab();
      else if (tabId === 'recruit') this.el.panelBody.innerHTML = this.recruitTab();
      else if (tabId === 'supply') this.el.panelBody.innerHTML = this.supplyTab();
      else if (tabId === 'quests') this.el.panelBody.innerHTML = this.questsTab();
      else this.el.panelBody.innerHTML = this.commandTab();
    }

    commandTab() {
      const g = this.game;
      const maxed = g.baseLevel >= 5;
      const cost = g.baseUpgradeCost();
      const can = g.canAfford(cost);
      const aliveSoldiers = g.soldiers.filter(s => !s.dead).length;
      return `<div class="hub-grid">
        <div class="hub-card wide">
          <h3><span class="num">HẠ TẦNG</span> NÂNG CẤP CĂN CỨ — CẤP ${g.baseLevel}/5</h3>
          <p>Tăng hiệu suất tháp súng, mở rộng biên chế và cải thiện tiếp tế mỗi ngày. Căn cứ mạnh hơn giúp bạn trụ vững qua các đêm.</p>
          <div class="hub-stat-row">
            <div class="hub-stat">SÁT THƯƠNG THÁP<b>+${(g.baseLevel - 1) * 12}%</b></div>
            <div class="hub-stat">BIÊN CHẾ TỐI ĐA<b>${2 + g.baseLevel} lính</b></div>
            <div class="hub-stat">ĐỢT ĐÃ SỐNG SÓT<b>${g.stats.nights}</b></div>
            <div class="hub-stat">CÔNG TRÌNH<b>${g.structures.filter(s => !s.dead).length}</b></div>
          </div>
          <div class="upgrade-base" style="margin-top:14px;padding:11px">
            <div><h3>${maxed ? 'CĂN CỨ ĐÃ ĐẠT CẤP TỐI ĐA' : 'NÂNG CẤP LÊN CẤP ' + (g.baseLevel + 1)}</h3>
            <p>${maxed ? 'Trạm 07 đã trở thành pháo đài thực sự.' : `Chi phí: ${cost.scrap} phế liệu · ${cost.parts} linh kiện`}</p></div>
            <button class="btn btn-primary" data-action="upgrade-base" ${maxed || !can ? 'disabled' : ''}>${maxed ? 'TỐI ĐA' : 'NÂNG CẤP'}</button>
          </div>
        </div>
        <div class="hub-card">
          <h3><span class="num">01</span> TÌNH HÌNH CHIẾN SỰ</h3>
          <div class="hub-stat-row">
            <div class="hub-stat">HẠ GỤC<b>${g.stats.kills}</b></div>
            <div class="hub-stat">VẬT TƯ ĐÃ MỞ<b>${g.stats.loots}</b></div>
            <div class="hub-stat">ĐÊM SỐNG SÓT<b>${g.stats.nights}</b></div>
          </div>
          <p style="margin-top:12px">Đồng đội đang trực chiến: <b style="color:#a7e05b">${aliveSoldiers}</b> / ${2 + g.baseLevel}</p>
        </div>
        <div class="hub-card">
          <h3><span class="num">02</span> LỢI ÍCH CĂN CỨ</h3>
          <p>• Tháp súng mạnh hơn theo cấp căn cứ.<br>• Chiêu mộ thêm lính bảo vệ.<br>• Tiếp tế giá tốt hơn mỗi ngày.<br>• Mở khóa thêm công trình phòng thủ.</p>
        </div>
        <div class="hub-card wide">
          <h3><span class="num">03</span> HÀNH ĐỘNG NHANH</h3>
          <div class="hub-stat-row" style="align-items:center">
            <button class="btn btn-ghost" data-action="build">▦ MỞ XÂY DỰNG</button>
            <button class="btn btn-ghost" data-action="tab" data-tab="weapons" style="display:none"></button>
            <span style="font-size:8px;color:#818a74;line-height:1.7">Tương tác với tường hoặc tháp súng để sửa chữa và nâng cấp.<br>
            Nhấn <kbd>B</kbd> để xây nhanh ngoài chiến trường. Nhấn <kbd>ESC</kbd> để đóng.</span>
          </div>
        </div>
      </div>`;
    }

    weaponsTab() {
      const g = this.game;
      const rows = g.player.weapons.map(w => {
        const cost = TT.WEAPON_UPGRADE_COST(w);
        const can = g.canAfford(cost) && w.owned && w.level < 5;
        const dmg = w.type === 'melee'
          ? w.damage * (1 + 0.2 * (w.level - 1))
          : w.damage * (1 + 0.2 * (w.level - 1)) * (w.pellets || 1);
        const reload = w.type === 'gun' ? (w.reloadTime * (1 - 0.06 * (w.level - 1))).toFixed(2) + 's' : '—';
        return `<div class="upgrade-row ${w.owned ? '' : 'locked-row'}">
          <div class="upgrade-icon">${w.icon}</div>
          <div class="upgrade-main">
            <h4>${w.name} ${w.owned ? '' : '· CHƯA MỞ KHÓA'}</h4>
            <div class="upgrade-stats">
              <span>SÁT THƯƠNG <b>${Math.round(dmg)}${w.pellets > 1 ? ' / phát' : ''}</b></span>
              <span>TỐC ĐỘ <b>${(1 / w.rate).toFixed(1)}/s</b></span>
              ${w.type === 'gun' ? `<span>BĂNG ĐẠN <b>${w.magSize}</b></span><span>NẠP <b>${reload}</b></span>` : '<span>TẦM <b>66</b></span>'}
            </div>
            <div class="pips">${[1, 2, 3, 4, 5].map(i => `<i class="pip ${i <= w.level ? 'on' : ''}"></i>`).join('')}</div>
            ${w.owned ? `<div class="upgrade-cost">${w.level >= 5 ? 'ĐÃ ĐẠT CẤP TỐI ĐA' : `NÂNG CẤP: <span class="${g.resources.scrap < cost.scrap ? 'lack' : ''}">${cost.scrap} phế liệu</span>${cost.parts ? ` · <span class="${g.resources.parts < cost.parts ? 'lack' : ''}">${cost.parts} linh kiện</span>` : ''}`}</div>` : '<div class="upgrade-cost">TÌM KHO VŨ KHÍ MÀU CAM TRONG VÙNG ĐỔ NÁT</div>'}
          </div>
          ${w.owned ? `<div class="upgrade-action"><button class="btn ${can ? 'btn-primary' : 'btn-ghost'}" data-action="upgrade-weapon" data-id="${w.id}" ${!can ? 'disabled' : ''}>${w.level >= 5 ? 'TỐI ĐA' : 'NÂNG CẤP'}</button></div>` : '<div class="upgrade-action"><span style="font-size:8px;color:#6f7863">KHÓA</span></div>'}
        </div>`;
      }).join('');
      return `<div class="weapon-upgrade-list">${rows}</div>
        <div class="empty-note" style="margin-top:12px;text-align:left">Mỗi cấp tăng 20% sát thương và giảm 6% thời gian nạp. Đạn được mua tại tab TIẾP TẾ hoặc nhặt trong đổ nát.</div>`;
    }

    recruitTab() {
      const g = this.game;
      const maxSoldiers = 2 + g.baseLevel;
      const alive = g.soldiers.filter(s => !s.dead);
      const cost = { scrap: 45, food: 10, parts: 1 };
      const can = g.canAfford(cost) && alive.length < maxSoldiers;
      const rows = alive.length ? alive.map(s => `<div class="soldier-row"><span>▸</span><span>${s.name}</span><span style="color:#758066">LÍNH SÚNG TRƯỜNG</span><span class="s-hp">${Math.ceil(s.hp)} / ${s.maxHp} HP</span></div>`).join('')
        : '<div class="empty-note">Chưa có đồng đội nào. Hãy chiêu mộ người đầu tiên.</div>';
      return `<div class="recruit-grid">
        <div class="recruit-card">
          <h3>CHIÊU MỘ LÍNH GÁC</h3>
          <p>Lính sẽ đi theo bạn khi ở gần căn cứ và tự động khai hỏa vào dị biến. Họ có thể hy sinh — hãy bảo vệ họ.</p>
          <div class="hub-stat-row">
            <div class="hub-stat">BIÊN CHẾ<b>${alive.length} / ${maxSoldiers}</b></div>
            <div class="hub-stat">SÁT THƯƠNG<b>${Math.round(13 + g.baseLevel * 1.5)}</b></div>
          </div>
          <button class="btn btn-primary" data-action="recruit" style="margin-top:12px;width:100%" ${can ? '' : 'disabled'}>CHIÊU MỘ · 45 PHẾ LIỆU · 10 LƯƠNG · 1 LINH KIỆN</button>
          ${alive.length >= maxSoldiers ? '<p style="margin-top:7px;color:#d9a76b">Đã đạt biên chế tối đa. Nâng cấp căn cứ để tăng giới hạn.</p>' : ''}
        </div>
        <div class="recruit-card">
          <h3>ĐỘI HÌNH HIỆN TẠI</h3>
          <div class="soldier-list">${rows}</div>
        </div>
      </div>`;
    }

    supplyTab() {
      const g = this.game;
      const items = [
        { id: 'ammo9', name: 'ĐẠN 9MM x24', cost: { scrap: 12 }, desc: 'Đạn cho súng lục.' },
        { id: 'shell', name: 'ĐẠN GHÉM x8', cost: { scrap: 18 }, desc: 'Đạn cho súng săn.', need: 'shotgun' },
        { id: 'ammo556', name: 'ĐẠN 5.56 x30', cost: { scrap: 24 }, desc: 'Đạn cho súng trường.', need: 'rifle' },
        { id: 'wood', name: 'GỖ x20', cost: { scrap: 15 }, desc: 'Vật liệu xây dựng.' },
        { id: 'medkit', name: 'BỘ Y TẾ x1', cost: { scrap: 18, food: 4 }, desc: 'Hồi 45 máu khi dùng.' },
        { id: 'parts', name: 'LINH KIỆN x1', cost: { scrap: 35, food: 2 }, desc: 'Nâng cấp vũ khí, căn cứ.' },
      ];
      const cards = items.map(it => {
        const locked = it.need && !g.player.weapons.find(w => w.id === it.need && w.owned);
        const costText = Object.entries(it.cost).map(([k, v]) => `${v} ${RES_LABEL[k]}`).join(' · ');
        return `<div class="shop-item">
          <h4>${it.name}</h4>
          <div class="price">${costText}</div>
          <p style="font-size:8px;color:#818a74;margin:0 0 8px">${locked ? 'Cần mở khóa ' + (it.need === 'shotgun' ? 'SÚNG SĂN' : 'SÚNG TRƯỜNG') : it.desc}</p>
          <button class="btn btn-ghost" data-action="buy" data-id="${it.id}" ${locked || !g.canAfford(it.cost) ? 'disabled' : ''}>MUA</button>
        </div>`;
      }).join('');
      return `<div class="shop-grid">${cards}</div>
        <div class="empty-note" style="margin-top:12px;text-align:left">Tiếp tế được bán bởi những người sống sót còn lại. Giá sẽ giảm 5% mỗi cấp căn cứ (tối đa 25%).</div>`;
    }

    questsTab() {
      const g = this.game;
      const cards = g.activeQuests.map(q => {
        const done = q.progress >= q.target;
        const pct = U.clamp(q.progress / q.target, 0, 1) * 100;
        return `<div class="quest-card ${done ? 'done' : ''}">
          <div class="qtag">${done ? 'HOÀN THÀNH' : q.tag}</div>
          <h3>${q.title}</h3>
          <p>${q.desc}</p>
          <div class="quest-bar"><i style="width:${pct}%"></i></div>
          <div class="quest-meta"><span>${Math.min(q.target, Math.floor(q.progress))} / ${q.target}</span><span class="quest-reward">${this.rewardText(q.reward)}</span></div>
        </div>`;
      }).join('');
      return `<div class="quest-board">${cards || '<div class="empty-note">Không còn nhiệm vụ. Hãy tiếp tục sinh tồn.</div>'}</div>
        <div class="empty-note" style="margin-top:12px;text-align:left">Đã hoàn thành: <b style="color:#a7e05b">${g.stats.quests}</b> nhiệm vụ. Phần thưởng được trao tự động khi mục tiêu đạt được.</div>`;
    }

    rewardText(reward) {
      const parts = [];
      if (reward.xp) parts.push(`+${reward.xp} XP`);
      for (const k of ['scrap', 'wood', 'food', 'parts', 'medkit']) {
        if (reward[k]) parts.push(`+${reward[k]} ${RES_LABEL[k]}`);
      }
      for (const k of ['ammo9', 'shell', 'ammo556']) {
        if (reward[k]) parts.push(`+${reward[k]} ${AMMO_LABEL[k]}`);
      }
      return parts.join(' · ');
    }

    /* ---------------- SCREENS ---------------- */
    showMenu() {
      this.el.menu.classList.remove('hidden');
      this.el.pause.classList.add('hidden');
      this.el.death.classList.add('hidden');
      this.el.panel.classList.add('hidden');
      this.el.guide.classList.add('hidden');
      this.el.buildBar.classList.add('hidden');
      this.hideHud();
    }
    showPause() {
      const g = this.game;
      this.el.pause.classList.remove('hidden');
      this.el.pauseStats.innerHTML = `
        <div><span>NGÀY</span><b>${g.day}</b></div>
        <div><span>HẠ GỤC</span><b>${g.stats.kills}</b></div>
        <div><span>ĐÊM SỐNG SÓT</span><b>${g.stats.nights}</b></div>`;
    }
    showDeath() {
      const g = this.game;
      this.el.death.classList.remove('hidden');
      this.el.deathStats.innerHTML = `
        <div><span>NGÀY</span><b>${g.day}</b></div>
        <div><span>HẠ GỤC</span><b>${g.stats.kills}</b></div>
        <div><span>ĐÊM SỐNG SÓT</span><b>${g.stats.nights}</b></div>
        <div><span>CẤP ĐỘ</span><b>${g.player.level}</b></div>`;
      const quotes = [
        '"Không ai chết một mình trong vùng đất chết."',
        '"Trạm 07 vẫn còn đó. Người tiếp theo sẽ tiếp tục."',
        '"Đêm nay, bầy dị biến lại có thêm một bữa ăn."',
        '"Bạn đã chiến đấu đến hơi thở cuối cùng."',
      ];
      this.el.deathEpitaph.textContent = quotes[Math.floor(Math.random() * quotes.length)];
    }
    showGuide() { this.el.guide.classList.remove('hidden'); }
    hideGuide() { this.el.guide.classList.add('hidden'); }
    showBuild() { this.el.buildBar.classList.remove('hidden'); this.refreshBuildBar(); }
    hideBuild() { this.el.buildBar.classList.add('hidden'); }
  }

  TT.UI = UI;
})();

