{"content": "/* ============================================================
   game.js — vòng lặp chính, chiến đấu, thời gian, căn cứ
   ============================================================ */
(function () {
  'use strict';
  const U = TT.U;
  const TAU = U.TAU;

  class Game {
    constructor() {
      this.canvas = document.getElementById('game');
      this.ctx = this.canvas.getContext('2d');
      this.W = window.innerWidth;
