312:         ly = U.clamp((this.input.mouse.y - this.H / 2) * 0.1, -45, 45) / this.cam.zoom;
313:       }
314:       const k = Math.min(1, dt * 7);
315:       this.cam.x += (p.x + lx - this.cam.x) * k;
316:       this.cam.y += (p.y + ly - this.cam.y) * k;
317:       const z = this.isTouch ? 0.88 : 1;
318:       this.cam.zoom += (z - this.cam.zoom) * Math.min(1, dt * 4);
319:       const hw = this.W / 2 / this.cam.zoom;
320:       const hh = this.H / 2 / this.cam.zoom;
321:       this.cam.x = U.clamp(this.cam.x, hw, this.world.size - hw);
322:       this.cam.y = U.clamp(this.cam.y, hh, this.world.size - hh);
