458:     setupStick(id, state) {
459:       const el = document.getElementById(id);
460:       if (!el) return;
461:       const knob = el.querySelector('.stick-knob');
462:       let pointerId = null;
463:       const update = (e) => {
464:         const r = el.getBoundingClientRect();
465:         const cx = r.left + r.width / 2;
466:         const cy = r.top + r.height / 2;
467:         let dx = e.clientX - cx;
468:         let dy = e.clientY - cy;
469:         const max = r.width * 0.32;
470:         const len = Math.hypot(dx, dy);
471:         if (len > max) { dx = (dx / len) * max; dy = (dy / len) * max; }
472:         state.x = dx / max;
473:         state.y = dy / max;
474:         state.mag = Math.min(1, len / max);
475:         state.active = true;
476:         knob.style.transform = `translate(${dx}px, ${dy}px)`;
477:       };
478:       el.addEventListener('pointerdown', (e) => {
479:         e.preventDefault();
