491:         if (pointerId !== null && e.pointerId !== pointerId) return;
492:         pointerId = null;
493:         state.x = 0; state.y = 0; state.mag = 0; state.active = false;
494:         knob.style.transform = '';
495:       };
496:       el.addEventListener('pointerup', end);
