510:         return;
511:       }
512:       if (this.state === 'menu') {
513:         if (code === 'Enter' || code === 'Space') this.startGame();
514:         else if (code === 'KeyG' || code === 'F1') this.openGuide();
515:         return;
516:       }
517:       if (this.state === 'dead') {
518:         if (code === 'Enter' || code === 'Space') this.startGame();
519:         return;
520:       }
521:       if (this.state === 'paused') {
522:         if (code === 'Escape' || code === 'KeyP') this.resume();
523:         return;
524:       }
525:       if (this.state === 'panel') {
526:         if (code === 'Escape' || code === 'KeyH' || code === 'KeyJ') this.closePanel();
527:         return;
528:       }
529:       if (this.state !== 'playing') return;
530: 
531:       if (code === 'Escape') {
532:         if (this.buildMode) this.toggleBuild(false);
533:         else this.pause();
534:         return;
535:       }
536:       if (code === 'Space') { this.tryDash(); return; }
537:       if (code === 'KeyE') { this.interact(); return; }
538:       if (code === 'KeyR') { this.player.startReload(); return; }
539:       if (code === 'KeyQ') { this.useMedkit(); return; }
540:       if (code === 'KeyB') { this.toggleBuild(); return; }
541:       if (code === 'KeyH') { this.openHub(); return; }
542:       if (code === 'KeyJ') { this.openPanel('quests'); return; }
543:       if (code === 'KeyP') { this.pause(); return; }
544:       if (code === 'KeyF') { this.toggleBuild(); return; }
545:       if (this.buildMode) {
546:         if (code === 'KeyR') { this.rotateBuild(); return; }
547:         const map = { Digit1: 'wall', Digit2: 'barricade', Digit3: 'turret', Digit4: 'medic' };
548:         if (map[code]) { this.selectBuild(map[code]); return; }
549:       }
550:       if (code.startsWith('Digit')) {
551:         const n = Number(code.slice(5));
552:         if (n >= 1 && n <= 4) this.player.switchWeapon(n - 1);
553:       }
554:       if (code === 'KeyM') {
555:         // chọn nhanh vũ khí kế tiếp
556:         const owned = this.player.weapons.map((w, i) => ({ w, i })).filter(o => o.w.owned);
557:         const idx = owned.findIndex(o => o.i === this.player.current);
558:         this.player.switchWeapon(owned[(idx + 1) % owned.length].i);
559:       }
560:     }
561:   }
